# ==== src/app/90-iran-cli.sh ====
# shellcheck shell=bash
# 90-iran-cli.sh - gemini-menu iran <command> ...   (the canonical command line)
#
# iran_cli returns the exit code; call it as its own statement (see act_run).
#   0 ok | 1 health: warnings | 2 health: broken / usage | 10 cancelled | 130 interrupted | other: failed

iran_usage() {
  cat <<EOF2
gemini-menu iran <command> [flags]

  (no command)            interactive menu
  status                  health check (exit 0 healthy, 1 warnings, 2 broken)
  setup                   install / repair the relay end to end
  repair [all|firewall|config|timer|register]
  register                register this IP with Shecan now, with a live check
  info [reveal]           IP, port, method, masked key, commands for the foreign side
  foreign-ip [IPv4]       change / re-check which IP may reach the relay (idempotent)
  domain list|add H|remove H|set H...
  logs [relay|timer|follow]     access-on [MIN]     access-off
  service start|stop|restart    timer on|off        telegram set|off
  backups [list|diff N|restore N|undo N]
  rollback [--backup-dir D]     undo the newest run that changed something
  uninstall               remove only what this tool created
  install-self            install this file as /usr/local/bin/gemini-menu (the timer runs it)
  watch                   one health-timer run (used by systemd)

Flags: --dry-run  --yes  --foreign-ip IP  --ss-port N  --key-file F  --shecan-url-file F
       --xray-version X.Y.Z  --xray-bin PATH  --backup-dir D  --verbose
EOF2
}

iran_cli_backup_dir() {  # the N-th newest backup directory (prints it)
  local n=${1:-} d
  v_int_range "$n" 1 999 || { ui_err "backup number: $IN_ERR"; return 2; }
  d=$(bk_dirs | sed -n "${n}p")
  if [[ -z $d ]]; then ui_err "no backup number $n (see: backups list)"; return 2; fi
  printf '%s' "$d"
}

iran_cli() {
  local c=${1:-status} d i=0
  shift || true
  case $c in
    status | health) iran_cli_status; return $? ;;
    setup | apply)   act_run "Setup" iran_act_setup; return $? ;;
    repair)          act_run "Repair ${1:-all}" iran_act_repair "${1:-all}"; return $? ;;
    register)        act_run "Register IP with Shecan" iran_act_register; return $? ;;
    info)
      if [[ ${1:-} == reveal ]]; then act_run "Reveal key" iran_act_reveal_key; else ACT_QUIET_OK=1 act_run "Connection info" iran_act_info; fi
      return $? ;;
    foreign-ip)      act_run "Allowed foreign IP" iran_act_change_ip "${1:-}"; return $? ;;
    domain | domains)
      case ${1:-list} in
        list)   ACT_QUIET_OK=1 act_run "Domain list" iran_act_domains_list ;;
        add)    act_run "Add domain" iran_act_domain_add "${2:-}" ;;
        remove) act_run "Remove domain" iran_act_domain_remove "${2:-}" ;;
        set)    shift; act_run "Set domain list" iran_act_domain_set "$@" ;;
        *)      ui_err "domain: use list | add H | remove H | set H..."; return 2 ;;
      esac
      return $? ;;
    logs)
      case ${1:-relay} in
        relay | last) ACT_QUIET_OK=1 act_run "Relay log" iran_act_logs relay ;;
        timer)        ACT_QUIET_OK=1 act_run "Timer log" iran_act_logs timer ;;
        follow)       iran_logs_follow ;;
        access)       act_run "Access log on" iran_act_access_on "${2:-}" ;;
        *)            ui_err "logs: use relay | timer | follow"; return 2 ;;
      esac
      return $? ;;
    access-on)       act_run "Access log on" iran_act_access_on "${1:-}"; return $? ;;
    access-off)      act_run "Access log off" iran_act_access_off; return $? ;;
    service)         act_run "Service ${1:-}" iran_act_service "${1:-}"; return $? ;;
    timer)           act_run "Health timer ${1:-}" iran_act_timer "${1:-}"; return $? ;;
    telegram)
      case ${1:-set} in
        set) act_run "Telegram alerts" iran_act_tg_set ;;
        off) act_run "Remove Telegram alerts" iran_act_tg_off ;;
        *)   ui_err "telegram: use set | off"; return 2 ;;
      esac
      return $? ;;
    backups)
      case ${1:-list} in
        list)
          bk_dirs | while IFS= read -r d; do i=$((i + 1)); printf '  %d) %s  %s\n' "$i" "$(basename "$d")" "$(iran_bk_summary "$d")"; done
          if [[ -z $(bk_dirs) ]]; then ui_note "(no backups yet)"; fi
          return 0 ;;
        diff)    d=$(iran_cli_backup_dir "${2:-}") || return $?; ACT_QUIET_OK=1 act_run "Backup diff" iran_act_backup_diff "$d"; return $? ;;
        restore) d=$(iran_cli_backup_dir "${2:-}") || return $?; act_run "Restore backup" iran_act_backup_restore "$d"; return $? ;;
        undo)    d=$(iran_cli_backup_dir "${2:-}") || return $?; act_run "Undo run" iran_act_rollback "$d"; return $? ;;
        *)       ui_err "backups: use list | diff N | restore N | undo N"; return 2 ;;
      esac ;;
    rollback)        act_run "Rollback" iran_act_rollback; return $? ;;
    uninstall)       act_run "Uninstall the Iran relay" iran_act_uninstall; return $? ;;
    install-self)    act_run "Install this tool" iran_act_install_self; return $? ;;
    watch)           act_run "Health timer run" iran_act_watch; return $? ;;
    help)            iran_usage; return 0 ;;
    *)               ui_err "unknown iran command: $c"; iran_usage >&2; return 2 ;;
  esac
}

# ==== src/app/91-foreign-engine.sh ====
# shellcheck shell=bash
# 91-foreign-engine.sh - the foreign (3X-UI) side: locate the panel, read and patch its Xray
# template, write it back SAFELY, restart and verify.
#
# What is new compared with the previous script
#   * compare-and-swap (Finding 7): the template is read once at the start of an action; the write is
#     `UPDATE ... WHERE value = <exactly what was read>` inside one SQLite transaction. If anyone saved
#     in the panel in the meantime, nothing is written and the action says so. Rollback is guarded the
#     same way: it restores only if the template is still what this tool wrote.
#   * a refused write leaves no stray backup behind; a failed restart restores automatically.
#   * the template patch program (py_tpl) is the previous one, unchanged.

IRAN_IP=${IRAN_IP:-}
DB=${XUI_DB:-}
XRAY_BIN=""
XRAY_DIR=""
RESTART_CMD="systemctl restart x-ui"
FIX_SNIFFING=0 ALL_DOMAINS=0 QUICK=0 RESTORE_FULL_DB=0
TAG=ir-gemini                 # name of the outbound in the panel template
OFF_MARK=__gemini_off__       # inboundTag prefix that makes a rule match nothing (= switched off)
LEARN_SKIP_HOSTS=(mtalk.google.com android.clients.google.com play.googleapis.com firebaseinstallations.googleapis.com www.googleapis.com accounts.google.com)
LEARN_SKIP_SUFFIX=(gvt1.com)
COMMIT_FIX_IDS=""             # "" = no sniffing change, "all" or "1,2" = fix those inbounds in the same transaction
COMMIT_RESTORE_FILE=""        # JSON id -> sniffing text to put back in the same transaction
NC_OK=0
T_HAS=0 T_IP="" T_PORT="" T_FORM="" T_STATE=missing T_UDP=0 T_SCOPE=all T_NDOM=0 T_DOMAINS="" T_ACCESS=""

# ---------------------------------------------------------------- locate the panel -------------
sqlite_has_template() {
  [[ -f $1 ]] && [[ $(sqlite3 -readonly "$1" "select count(*) from settings where key='xrayTemplateConfig'" 2>/dev/null || echo 0) -ge 1 ]]
}

locate_db() {  # quiet; sets DB (or leaves it empty)
  local c cands=() folder seen=""
  if [[ -n $DB ]]; then
    if [[ -f $DB ]]; then return 0; fi
    return 1
  fi
  folder=$(systemctl show x-ui -p Environment --value 2>/dev/null | tr ' ' '\n' | sed -n 's/^XUI_DB_FOLDER=//p' | head -n 1 || true)
  if [[ -n $folder ]]; then cands+=("$folder/x-ui.db"); fi
  cands+=("$GM_ROOT/etc/x-ui/x-ui.db" "$GM_ROOT/usr/local/x-ui/db/x-ui.db" "$GM_ROOT/usr/local/x-ui/x-ui.db" "$GM_ROOT/opt/x-ui/x-ui.db")
  # only system locations: a copy in /root or /home is usually a backup, never the live panel database
  while IFS= read -r c; do cands+=("$c"); done < <(find "$GM_ROOT/etc" "$GM_ROOT/usr/local" "$GM_ROOT/opt" "$GM_ROOT/var/lib" -maxdepth 4 -name x-ui.db 2>/dev/null || true)
  for c in "${cands[@]}"; do
    if [[ -f $c && $seen != *"|$c|"* ]]; then
      seen+="|$c|"
      if sqlite_has_template "$c"; then DB=$c; return 0; fi
    fi
  done
  return 1
}

locate_xray() {  # quiet; sets XRAY_BIN / XRAY_DIR
  local c
  if [[ -z $XRAY_BIN && -n $XRAY_BIN_SRC ]]; then XRAY_BIN=$XRAY_BIN_SRC; fi
  if [[ -z $XRAY_BIN ]]; then
    for c in "$GM_ROOT"/usr/local/x-ui/bin/xray-linux-* "$GM_ROOT"/opt/x-ui/bin/xray-linux-*; do
      if [[ -f $c && -x $c ]]; then XRAY_BIN=$c; break; fi
    done
    if [[ -z $XRAY_BIN ]]; then
      XRAY_BIN=$(find "$GM_ROOT/usr/local" "$GM_ROOT/opt" "$GM_ROOT/root" -maxdepth 4 -type f -name 'xray-linux-*' -perm -u+x 2>/dev/null | head -n 1 || true)
    fi
  fi
  if [[ -n $XRAY_BIN && -x $XRAY_BIN ]]; then XRAY_DIR=$(dirname "$XRAY_BIN"); return 0; fi
  return 1
}

find_db() {
  if [[ -n $DB && ! -f $DB ]]; then act_fail "database not found: $DB"; fi
  locate_db || act_fail "could not find a 3X-UI database with an xrayTemplateConfig row.
  - Pass it explicitly with --db PATH.
  - If the panel never saved a custom template, open the panel -> Xray Configs, press Save once (no changes), then re-run."
  sqlite_has_template "$DB" || act_fail "$DB has no settings.xrayTemplateConfig row (open the panel -> Xray Configs and press Save once, then re-run)"
  ui_ok "3X-UI database: $DB"
}

find_xray() {
  locate_xray || act_fail "panel Xray binary not found; pass --xray-bin PATH"
  ui_ok "panel Xray: $XRAY_BIN ($("$XRAY_BIN" version 2>/dev/null | awk 'NR==1{print $1" "$2}'))"
  ui_note "use the same version on the Iran server: --xray-version $("$XRAY_BIN" version 2>/dev/null | awk 'NR==1{print $2}')"
}

need_panel() {  # inside an action
  need_cmds sqlite3 python3
  iran_require_root
  if [[ -z $DB ]]; then find_db; fi
  if [[ -z $XRAY_DIR ]]; then find_xray; fi
}

# ---------------------------------------------------------------- read the template -------------
# ftpl_read [FILE]  -> the stored template as text in FILE (default $GM_TMP/template.orig.json).
# Quiet and side-effect free (usable from probes); returns non-zero when unreadable / not JSON.
ftpl_read() {
  local out=${1:-$GM_TMP/template.orig.json}
  python3 - "$DB" "$out" <<'PY' || return 1
import sqlite3, sys
con = sqlite3.connect("file:%s?mode=ro" % sys.argv[1], uri=True, timeout=30)
row = con.execute("select value from settings where key='xrayTemplateConfig'").fetchone()
if row is None:
    sys.exit(1)
open(sys.argv[2], "w", encoding="utf-8", newline="").write(row[0])
PY
  python3 -c 'import json,sys;json.load(open(sys.argv[1]))' "$out" 2>/dev/null
}

# the same, for use inside an action: stops it with a clear message
ftpl_read_or_fail() {
  ftpl_read "$@" || act_fail "cannot read a valid Xray template from the panel database ($DB)"
}

panel_xray_test() {  # panel_xray_test CONFIG -> 0 if accepted by the panel's Xray; message in $GM_TMP/xtest.out
  ( cd "$XRAY_DIR" && XRAY_LOCATION_ASSET="$XRAY_DIR" "$XRAY_BIN" run -test -config "$1" >"$GM_TMP/xtest.out" 2>&1 ) \
    || ( cd "$XRAY_DIR" && XRAY_LOCATION_ASSET="$XRAY_DIR" "$XRAY_BIN" -test -config "$1" >"$GM_TMP/xtest.out" 2>&1 )
}
xray_err() { grep -v -i 'deprecated\|^Xray \|^A unified\|Reading config' "$GM_TMP/xtest.out" | tail -n 3; }

# ---------------------------------------------------------------- template patch program -----
# (unchanged from the previous script)
# ---------------------------------------------------------------------------
# One program for every template edit. Usage: py_tpl MODE IN [OUT]  (parameters in P_* env vars)
#   patch    full setup patch (P_FORM P_IP P_PORT P_KEY P_METHOD P_DOMAINS)
#   inspect  print shell assignments describing the current state
#   toggle   P_STATE=on|off         scope  P_TAGS="tag tag" (empty = all inbounds)
#   domains  P_DOMAINS="a b c"      revert   remove ir-gemini + its rules
#   logaccess P_ACCESS=path|none    diff   P_IN2=other template (summary of differences)
# A rule is "switched off" by prefixing its inboundTag entries with __gemini_off__: it stays in the
# template but can never match. Scope is the inboundTag list on the two Gemini rules.
py_tpl() {
  M=$1 P_IN=$2 P_OUT=${3:-} P_TAG=$TAG P_OFF=$OFF_MARK python3 - <<'PY'
import json, os, re, shlex, sys
e = os.environ
mode = e["M"]
GEM, OLD, OFF = e["P_TAG"], "gemini-shecan", e["P_OFF"]
say = print

def fail(m):
    print("PATCH-ERROR: " + m, file=sys.stderr)
    sys.exit(2)

text = open(e["P_IN"], encoding="utf-8").read()
tpl = json.loads(text)
orig = json.loads(text)
doms = ["full:" + d for d in e.get("P_DOMAINS", "").split()]

def parse_state(rule):
    tags = rule.get("inboundTag")
    if isinstance(tags, str):
        tags = [tags]
    if not tags:
        return False, []
    if all(t == OFF or t.startswith(OFF + "/") for t in tags):
        return True, [t[len(OFF) + 1:] for t in tags if t != OFF]
    return False, list(tags)

def set_state(rule, off, scope):
    if off:
        rule["inboundTag"] = [OFF + "/" + t for t in scope] if scope else [OFF]
    elif scope:
        rule["inboundTag"] = list(scope)
    else:
        rule.pop("inboundTag", None)

def find_rules(rules):
    gem = next((r for r in rules if r.get("outboundTag") == GEM and r.get("domain")), None)
    udp = None
    if gem:
        udp = next((r for r in rules if r is not gem and r.get("network") == "udp"
                    and str(r.get("port")) == "443" and r.get("domain") == gem["domain"]), None)
    return gem, udp

def need_rules(t):
    rr = t.get("routing", {}).get("rules")
    if not isinstance(t.get("outbounds"), list) or not isinstance(rr, list):
        fail("template has no outbounds/routing.rules")
    return rr

def dangling(t):
    tags = {o.get("tag") for o in t.get("outbounds", [])}
    if isinstance(t.get("api"), dict) and t["api"].get("tag"):
        tags.add(t["api"]["tag"])            # the virtual 'api' outbound
    bals = {b.get("tag") for b in t.get("routing", {}).get("balancers", [])}
    bad = set()
    for r in t.get("routing", {}).get("rules", []):
        if "outboundTag" in r and r["outboundTag"] not in tags:
            bad.add(("outboundTag", r["outboundTag"]))
        if "balancerTag" in r and r["balancerTag"] not in bals:
            bad.add(("balancerTag", r["balancerTag"]))
    return bad

def rsum(r):
    p = []
    if r.get("inboundTag"):
        p.append("in:" + ",".join(r["inboundTag"])[:28])
    if r.get("network"):
        p.append(str(r["network"]) + ("/" + str(r["port"]) if r.get("port") else ""))
    if r.get("domain"):
        p.append("%d domains" % len(r["domain"]))
    if r.get("protocol"):
        p.append("proto:" + ",".join(r["protocol"]) if isinstance(r["protocol"], list) else "proto:" + str(r["protocol"]))
    if r.get("ip"):
        p.append("ip:" + ",".join(r["ip"])[:20])
    return " ".join(p) + " -> " + str(r.get("outboundTag") or "bal:" + str(r.get("balancerTag")))

def shq(v):
    return shlex.quote(str(v))

# ------------------------------------------------------------------ inspect --
if mode == "inspect":
    outs = [o for o in tpl.get("outbounds", []) if o.get("tag") == GEM]
    ip = port = form = ""
    if outs:
        s = outs[0].get("settings", {})
        form = "servers" if "servers" in s else "flat"
        if form == "servers":
            s = (s["servers"] or [{}])[0]
        ip, port = s.get("address", ""), s.get("port", "")
    rules = tpl.get("routing", {}).get("rules", []) if isinstance(tpl.get("routing"), dict) else []
    g, u = find_rules(rules)
    state, scope, nd, dl = "missing", [], 0, ""
    if g:
        off, scope = parse_state(g)
        state = "off" if off else "on"
        if u is None or parse_state(u) != (off, scope):
            state = "partial"
        dl = [d[5:] if d.startswith("full:") else d for d in g["domain"]]
        nd, dl = len(dl), " ".join(dl)
    for k, v in (("T_HAS", 1 if outs else 0), ("T_IP", ip), ("T_PORT", port), ("T_FORM", form), ("T_STATE", state),
                 ("T_UDP", 1 if u else 0), ("T_SCOPE", ",".join(scope) or "all"), ("T_NDOM", nd), ("T_DOMAINS", dl),
                 ("T_ACCESS", (tpl.get("log") or {}).get("access", "__unset__"))):
        print("%s=%s" % (k, shq(v)))
    sys.exit(0)

# --------------------------------------------------------------------- diff --
if mode == "diff":
    other = json.load(open(e["P_IN2"], encoding="utf-8"))
    def tags(t): return sorted(o.get("tag", "?") for o in t.get("outbounds", []))
    a_t, b_t = tags(tpl), tags(other)
    for t in b_t:
        if t not in a_t: say("+ outbound '%s' comes back" % t)
    for t in a_t:
        if t not in b_t: say("- outbound '%s' goes away" % t)
    ar = [rsum(r) for r in tpl.get("routing", {}).get("rules", [])]
    br = [rsum(r) for r in other.get("routing", {}).get("rules", [])]
    for s in br:
        if s not in ar: say("+ rule: " + s)
    for s in ar:
        if s not in br: say("- rule: " + s)
    la, lb = (tpl.get("log") or {}).get("access"), (other.get("log") or {}).get("access")
    if la != lb: say("~ log.access: %s -> %s" % (la, lb))
    rest = [k for k in set(tpl) | set(other) if k not in ("outbounds", "routing", "log") and tpl.get(k) != other.get(k)]
    if rest: say("~ other sections differ: " + ", ".join(sorted(rest)))
    if tpl == other: say("= identical")
    if e.get("P_OUT"):
        open(e["P_OUT"], "w", encoding="utf-8").write(open(e["P_IN2"], encoding="utf-8").read())
        open(e["P_OUT"] + ".changed", "w").write("1" if tpl != other else "0")
    sys.exit(0)

# ------------------------------------------------------ modes that modify --
outs = tpl.get("outbounds")
rules = need_rules(tpl)
routing = tpl["routing"]
gem_rule, udp_rule = find_rules(rules)

if mode == "patch":
    carry = parse_state(gem_rule) if gem_rule else None     # keep an existing scope / off switch
    outs[:] = [o for o in outs if o.get("tag") != OLD] if any(o.get("tag") == OLD for o in outs) else outs
    if len(outs) != len(orig["outbounds"]): say("- removed outbound '%s'" % OLD)
    gone_bal = set()
    if isinstance(routing.get("balancers"), list):
        keep = []
        for b in routing["balancers"]:
            if "gemini" in json.dumps(b).lower(): gone_bal.add(b.get("tag")); say("- removed balancer '%s'" % b.get("tag"))
            else: keep.append(b)
        if keep: routing["balancers"] = keep
        else: del routing["balancers"]
    for key in ("observatory", "burstObservatory"):
        o = tpl.get(key)
        if isinstance(o, dict) and isinstance(o.get("subjectSelector"), list):
            sel = o["subjectSelector"]
            keep = [s for s in sel if "gemini" not in str(s).lower()]
            if len(keep) != len(sel):
                say("- removed gemini selectors from %s" % key)
                if keep: o["subjectSelector"] = keep
                else: del tpl[key]
    old_dom = gem_rule["domain"] if gem_rule else None
    def ours_udp(r):
        return r.get("network") == "udp" and str(r.get("port")) == "443" and r.get("domain") in (doms, old_dom)
    kept = []
    for r in rules:
        if r.get("outboundTag") in (OLD, GEM) or r.get("balancerTag") in gone_bal or ours_udp(r):
            say("- removed rule -> %s" % (r.get("outboundTag") or r.get("balancerTag")))
        else:
            kept.append(r)
    rules[:] = kept
    srv = {"address": e["P_IP"], "port": int(e["P_PORT"]), "method": e["P_METHOD"], "password": e["P_KEY"]}
    ob = {"tag": GEM, "protocol": "shadowsocks", "settings": {"servers": [srv]} if e["P_FORM"] == "servers" else srv}
    idx = next((i for i, o in enumerate(outs) if o.get("tag") == GEM), None)
    if idx is None:
        outs.append(ob)          # never at index 0: the first outbound is the default one
        say("+ added outbound '%s' (%s form, appended last so the default outbound is unchanged)" % (GEM, e["P_FORM"]))
    else:
        outs[idx] = ob
        say("+ replaced existing outbound '%s' in place" % GEM)
    def is_bt(r):
        p = r.get("protocol")
        p = [p] if isinstance(p, str) else (p or [])
        return "bittorrent" in p and r.get("outboundTag")
    pos = next((i for i, r in enumerate(rules) if is_bt(r)), None)
    if pos is None:
        fail("no 'bittorrent -> blocked' rule found in the template; refusing to guess where to insert")
    block = rules[pos]["outboundTag"]
    new_udp = {"type": "field", "network": "udp", "port": "443", "domain": list(doms), "outboundTag": block}
    new_gem = {"type": "field", "domain": list(doms), "outboundTag": GEM}
    if carry:
        set_state(new_udp, *carry); set_state(new_gem, *carry)
        if carry[0] or carry[1]: say("= kept the existing scope/switch of the Gemini rules")
    rules[pos + 1:pos + 1] = [new_udp, new_gem]
    say("+ inserted 2 rules after rule #%d (bittorrent -> %s): udp/443 -> %s, domains -> %s" % (pos, block, block, GEM))

elif mode == "toggle":
    if not gem_rule: fail("the Gemini rules are not in the template yet - run setup first")
    want_off = e["P_STATE"] == "off"
    for r in (gem_rule, udp_rule):
        if r is not None:
            _, scope = parse_state(r)
            set_state(r, want_off, scope)
    say("~ Gemini routing -> %s" % ("OFF (rules stay in the template but match nothing)" if want_off else "ON"))
    if udp_rule is None: say("! the udp/443 block rule is missing (QUIC is not blocked)")

elif mode == "scope":
    if not gem_rule: fail("the Gemini rules are not in the template yet - run setup first")
    tags = e.get("P_TAGS", "").split()
    for r in (gem_rule, udp_rule):
        if r is not None:
            off, _ = parse_state(r)
            set_state(r, off, tags)
    say("~ scope -> %s" % (", ".join(tags) if tags else "all inbounds"))

elif mode == "domains":
    if not gem_rule: fail("the Gemini rules are not in the template yet - run setup first")
    if not doms: fail("the domain list cannot be empty")
    old = [d[5:] if d.startswith("full:") else d for d in gem_rule["domain"]]
    new = [d[5:] for d in doms]
    for d in new:
        if d not in old: say("+ " + d)
    for d in old:
        if d not in new: say("- " + d)
    gem_rule["domain"] = list(doms)
    if udp_rule is not None: udp_rule["domain"] = list(doms)

elif mode == "revert":
    n = len(outs)
    outs[:] = [o for o in outs if o.get("tag") not in (GEM, OLD)]
    if len(outs) != n: say("- removed outbound '%s'" % GEM)
    kept = []
    for r in rules:
        if r is gem_rule or r is udp_rule or r.get("outboundTag") in (GEM, OLD):
            say("- removed rule: " + rsum(r))
        else:
            kept.append(r)
    rules[:] = kept

elif mode == "logaccess":
    a = e["P_ACCESS"]
    tpl.setdefault("log", {})["access"] = a
    say("~ log.access: %s -> %s" % ((orig.get("log") or {}).get("access", "(unset)"), a))

else:
    fail("unknown mode " + mode)

new_bad = dangling(tpl) - dangling(orig)
if new_bad: fail("dangling references after the change: %s" % sorted(new_bad))
for k, v in sorted(dangling(orig)): say("! pre-existing dangling %s '%s' (not touched)" % (k, v))

m = re.search(r"\n( +)\"", text)
indent = len(m.group(1)) if m else (None if "\n" not in text else 2)
open(e["P_OUT"], "w", encoding="utf-8").write(json.dumps(tpl, indent=indent, ensure_ascii=False))
open(e["P_OUT"] + ".changed", "w").write("1" if tpl != orig else "0")
PY
}

# ---------------------------------------------------------------- database program -------------
# panel_py MODE ...   one program for everything that touches the panel database besides the
# template text itself.
#   audit    DB COUNTFILE        human report of inbounds whose sniffing would stop domain rules; count -> file
#   list     DB                  id remark port protocol problems   (flagged inbounds)   fields separated by \x1f
#   inbounds DB                  tag port remark protocol           (enabled client inbounds)  fields separated by \x1f
#   (\x1f, not a tab: tabs collapse in `read`, which would shift fields when a remark is empty)
#   commit   DB BASE NEW BKDIR FIXIDS RESTOREFILE
#            ONE transaction: template compare-and-swap (BASE = text read earlier, NEW = "-" to skip),
#            optional sniffing fix / restore. Exit 3 = CONFLICT, nothing written.
#   restore  DB BKDIR EXPECTED   put the saved template (+ sniffing) back. EXPECTED = file holding the text
#            the template must STILL be (compare-and-swap), or "-" to restore unconditionally. Exit 3 = CONFLICT.
panel_py() {
  python3 - "$@" <<'PY'
import json, os, sqlite3, sys

mode, db = sys.argv[1], sys.argv[2]
rw = mode in ("commit", "restore")
con = sqlite3.connect("file:%s?mode=%s" % (db, "rw" if rw else "ro"), uri=True, timeout=30, isolation_level=None)


def flagged_inbounds():
    cols = [r[1] for r in con.execute("pragma table_info(inbounds)")]
    if "sniffing" not in cols:
        return None, 0, 0
    flagged, disabled, total = [], 0, 0
    for iid, remark, port, proto, enable, sn in con.execute(
            "select id, remark, port, protocol, enable, sniffing from inbounds order by id"):
        if proto in ("tunnel", "dokodemo-door"):
            continue
        total += 1
        if not enable:
            disabled += 1
            continue
        try:
            s = json.loads(sn) if sn else {}
        except Exception:
            s = {}
        probs = []
        if not s.get("enabled"):
            probs.append("sniffing disabled")
        else:
            d = s.get("destOverride") or []
            if "tls" not in d: probs.append("lacks tls")
            if "http" not in d: probs.append("lacks http")
            if s.get("routeOnly"): probs.append("routeOnly=true")
            if s.get("metadataOnly"): probs.append("metadataOnly=true")
        if probs:
            flagged.append((iid, remark, port, proto, probs, sn, s))
    return flagged, disabled, total


def clean(v):
    return "".join(ch for ch in str(v) if ch.isprintable() and ch not in "\t\n")


if mode == "audit":
    out = sys.argv[3]
    flagged, disabled, total = flagged_inbounds()
    if flagged is None:
        print("  (this panel version has no inbounds.sniffing column - audit skipped)")
        open(out, "w").write("0")
        sys.exit(0)
    print("  %d client inbound(s) checked (%d disabled and skipped)" % (total, disabled))
    for iid, remark, port, proto, probs, _, _ in flagged:
        print("  ! id=%s %-18s port=%-5s %-12s %s" % (iid, clean(remark)[:18], port, proto, ", ".join(probs)))
    if not flagged:
        print("  all enabled inbounds have sniffing with tls+http and no routeOnly/metadataOnly")
    open(out, "w").write(str(len(flagged)))

elif mode == "list":
    flagged, _, _ = flagged_inbounds()
    for iid, remark, port, proto, probs, _, _ in (flagged or []):
        print("\x1f".join([str(iid), clean(remark), str(port), str(proto), ", ".join(probs)]))

elif mode == "inbounds":
    for tag, port, remark, proto, en in con.execute("select tag, port, remark, protocol, enable from inbounds order by id"):
        if proto in ("tunnel", "dokodemo-door") or not en:
            continue
        print("\x1f".join([clean(tag), str(port), clean(remark), str(proto)]))

elif mode == "commit":
    base_f, new_f, bk, fix, restore_f = sys.argv[3:8]
    con.execute("BEGIN IMMEDIATE")
    try:
        if new_f != "-":
            base = open(base_f, encoding="utf-8", newline="").read()
            new = open(new_f, encoding="utf-8", newline="").read()
            n = con.execute("update settings set value=? where key='xrayTemplateConfig' and value=?", (new, base)).rowcount
            if n != 1:
                con.execute("ROLLBACK")
                print("CONFLICT: the template in the panel is not what was read")
                sys.exit(3)
        saved_path = os.path.join(bk, "sniffing.orig.json")
        saved = json.load(open(saved_path)) if os.path.exists(saved_path) else {}
        if fix:
            flagged, _, _ = flagged_inbounds()
            want = None if fix == "all" else set(fix.split(","))
            n_fix = 0
            for iid, remark, port, proto, probs, sn, s in (flagged or []):
                if want is not None and str(iid) not in want:
                    continue
                saved.setdefault(str(iid), sn)
                s["enabled"] = True
                d = list(s.get("destOverride") or [])
                for x in ("http", "tls"):
                    if x not in d: d.append(x)
                s["destOverride"], s["routeOnly"], s["metadataOnly"] = d, False, False
                n = con.execute("update inbounds set sniffing=? where id=? and sniffing is ?",
                                (json.dumps(s, indent=2), iid, sn)).rowcount
                if n != 1:
                    con.execute("ROLLBACK")
                    print("CONFLICT: inbound %s was changed in the panel while this ran" % iid)
                    sys.exit(3)
                n_fix += 1
            print("  sniffing fixed on %d inbound(s)" % n_fix)
        if restore_f:
            for iid, val in json.load(open(restore_f)).items():
                row = con.execute("select sniffing from inbounds where id=?", (int(iid),)).fetchone()
                if row is None:
                    continue
                saved.setdefault(str(iid), row[0])
                con.execute("update inbounds set sniffing=? where id=?", (val, int(iid)))
            print("  sniffing values restored")
        if saved:
            json.dump(saved, open(saved_path, "w"))
        con.execute("COMMIT")
    except SystemExit:
        raise
    except Exception:
        con.execute("ROLLBACK")
        raise

elif mode == "restore":
    bk, expected = sys.argv[3:5]
    con.execute("BEGIN IMMEDIATE")
    tpl = open(os.path.join(bk, "template.orig.json"), encoding="utf-8", newline="").read()
    if expected == "-":
        n = con.execute("update settings set value=? where key='xrayTemplateConfig'", (tpl,)).rowcount
    else:
        exp = open(expected, encoding="utf-8", newline="").read()
        n = con.execute("update settings set value=? where key='xrayTemplateConfig' and value=?", (tpl, exp)).rowcount
    if n != 1:
        con.execute("ROLLBACK")
        print("CONFLICT: the template in the panel is no longer what this run wrote")
        sys.exit(3)
    sp = os.path.join(bk, "sniffing.orig.json")
    if os.path.exists(sp):
        for iid, val in json.load(open(sp)).items():
            con.execute("update inbounds set sniffing=? where id=?", (val, int(iid)))
    con.execute("COMMIT")
    print("restored the saved template%s" % (" and sniffing values" if os.path.exists(sp) else ""))
PY
}

# ---------------------------------------------------------------- facts about the panel ---------
# foreign_facts: reads the template and sets the T_* variables. Quiet; returns 1 on failure.
foreign_facts() {
  T_HAS=0 T_IP="" T_PORT="" T_FORM="" T_STATE=missing T_UDP=0 T_SCOPE=all T_NDOM=0 T_DOMAINS="" T_ACCESS=""
  [[ -n $DB ]] || return 1
  local f=$GM_TMP/facts.$BASHPID.json
  ftpl_read "$f" >/dev/null 2>&1 || return 1
  eval "$(py_tpl inspect "$f")"
  return 0
}

foreign_domain_list() {  # the hosts currently routed (falls back to the built-in 9)
  if foreign_facts && [[ $T_NDOM -gt 0 ]]; then printf '%s\n' $T_DOMAINS; else printf '%s\n' "${GEMINI_DOMAINS[@]}"; fi
}

# ---------------------------------------------------------------- restart + verify ---------------
restart_panel() {
  ui_note "restarting the panel: $RESTART_CMD"
  bash -c "$RESTART_CMD" || return 1
}

# wait_xray present|absent [BEFORE_MTIME]: the panel's Xray runs again and its regenerated config has/lacks our tag
wait_xray() {
  local want=$1 before=${2:-} i cfg="$XRAY_DIR/config.json" ok now_m
  for i in $(seq 1 "${GM_WAIT_XRAY:-30}"); do
    sleep "${GM_XRAY_POLL:-1}"
    # exact process-name match (comm is cut to 15 chars); -f would also match this script's own arguments
    pgrep -x "$(basename "$XRAY_BIN" | cut -c1-15)" >/dev/null 2>&1 || continue
    if [[ -f $cfg ]]; then
      ok=0
      if grep -q "\"$TAG\"" "$cfg"; then ok=1; fi
      if [[ ($want == present && $ok == 1) || ($want == absent && $ok == 0) ]]; then
        now_m=$(stat -c %Y "$cfg" 2>/dev/null || echo "")
        if [[ -n $before && $now_m == "$before" ]]; then
          ui_warn "the panel did not rewrite $cfg on restart - the match is against the previous file"
        fi
        return 0
      fi
    else
      return 0    # config.json is somewhere else; process check only
    fi
  done
  return 1
}

# after restoring $BK/template.orig.json the tag is present only if that saved template had it
expect_after_restore() { if grep -q "\"$TAG\"" "$1/template.orig.json"; then echo present; else echo absent; fi; }

# ---------------------------------------------------------------- the commit pipeline ------------
foreign_drop_backup() {  # rollback hook: the write was refused, so nothing happened - leave no stray backup
  if [[ -n ${1:-} && -d $1 ]]; then rm -rf "$1"; fi
}

# Runs when something fails AFTER the database write (restart / verification).
foreign_auto_restore() {  # foreign_auto_restore BKDIR
  local bk=$1 rc=0 exp=$1/template.new.json
  ui_warn "restoring the previous template..."
  [[ -f $exp ]] || exp=-
  panel_py restore "$DB" "$bk" "$exp" || rc=$?
  if ((rc != 0)); then
    ui_err "automatic restore FAILED (exit $rc) - the new template is still in the panel database"
    act_partial "the new template was written to the panel database (backup: $bk)"
    act_tip "restore it with: gemini-menu foreign rollback   (or from the panel: Xray Configs)"
    return 0
  fi
  if restart_panel && wait_xray "$(expect_after_restore "$bk")"; then
    ui_ok "previous template restored; the panel's Xray is running again"
  else
    ui_warn "template restored, but the panel did not confirm a healthy restart - check: systemctl status x-ui"
  fi
  return 0
}

# foreign_commit NEWFILE
#   The BASE is $GM_TMP/template.orig.json: the template as read at the start of this action.
#   COMMIT_FIX_IDS / COMMIT_RESTORE_FILE ride in the same transaction (and the same restart).
foreign_commit() {
  local nf=$1 want rc=0 changed=1 mt0=""
  if [[ $(<"$nf.changed") == 0 ]]; then changed=0; fi
  if ((!changed)) && [[ -z $COMMIT_FIX_IDS && -z $COMMIT_RESTORE_FILE ]]; then
    ui_ok "nothing to change - it is already like this"
    return 0
  fi
  if ((changed)); then
    panel_xray_test "$nf" || act_fail "the panel's Xray rejected the new template: $(xray_err | tr '\n' ' ') - nothing was written"
    ui_ok "new template validated with the panel's Xray"
  fi
  if is_dry; then dry_say "would back up the DB, write the template (compare-and-swap), restart: $RESTART_CMD"; return 0; fi
  confirm_typed "The panel will restart ($RESTART_CMD).
  This drops ALL user connections for a few seconds." yes || act_cancel

  act_step "Back up the panel database"
  BK=""                                       # every commit gets its own backup folder
  bk_dir
  sqlite3 "$DB" ".backup '$BK/x-ui.db'"
  chmod 600 "$BK/x-ui.db"
  [[ $(sqlite3 "$BK/x-ui.db" 'pragma integrity_check') == ok ]] || act_fail "the DB backup failed its integrity check"
  cp "$GM_TMP/template.orig.json" "$BK/template.orig.json"
  if ((changed)); then cp "$nf" "$BK/template.new.json"; fi
  printf 'DB\t%s\nXRAY\t%s\nRESTART\t%s\n' "$DB" "$XRAY_BIN" "$RESTART_CMD" >"$BK/$MANIFEST.pending"
  ui_ok "backup: $BK"
  act_on_fail foreign_drop_backup "$BK"

  act_step "Write the template (compare-and-swap)"
  panel_py commit "$DB" "$GM_TMP/template.orig.json" "$([[ $changed == 1 ]] && echo "$nf" || echo -)" "$BK" "$COMMIT_FIX_IDS" "$COMMIT_RESTORE_FILE" || rc=$?
  if ((rc == 3)); then
    act_fail "the panel's settings were changed by someone else after this tool read them (a save in the panel?). NOTHING was written. Review the panel, then run it again."
  elif ((rc != 0)); then
    act_fail "the database write failed (exit $rc); nothing was changed"
  fi
  mv -f "$BK/$MANIFEST.pending" "$BK/$MANIFEST"
  act_commit                                  # the write happened: the backup is now needed, keep it
  act_on_fail foreign_auto_restore "$BK"      # ...and a failed restart puts the old template back

  act_step "Restart the panel and verify"
  [[ -f $XRAY_DIR/config.json ]] && mt0=$(stat -c %Y "$XRAY_DIR/config.json" 2>/dev/null || true)
  restart_panel || act_fail "restarting the panel failed (command: $RESTART_CMD)"
  if grep -q "\"$TAG\"" "$nf"; then want=present; else want=absent; fi
  if ((!changed)); then want=any; fi      # sniffing-only change: the template (and our tag) did not move
  if [[ $want != any ]]; then
    wait_xray "$want" "$mt0" || act_fail "Xray did not come up as expected (generated config should be '$want' for $TAG) within ${GM_WAIT_XRAY:-30} s"
  else
    wait_xray present "$mt0" || wait_xray absent "$mt0" || act_fail "the panel's Xray did not come back"
  fi
  act_commit
  ui_ok "panel restarted; Xray is running with the new settings"
}

foreign_tpl_action() {  # foreign_tpl_action MODE   (P_* parameters set by the caller)
  need_panel
  ftpl_read_or_fail
  if ! py_tpl "$1" "$GM_TMP/template.orig.json" "$GM_TMP/new.json" | sed 's/^/  /'; then act_fail "could not compute the change"; fi
  foreign_commit "$GM_TMP/new.json"
}

# ---------------------------------------------------------------- safe sync to the Iran relay -----
# foreign_sync_cmd OUT host...  -> the command to run ON the Iran server. Every word is shell-quoted
# with printf %q, and every host must be a valid hostname: nothing a log line can contain reaches a shell.
foreign_sync_cmd() {
  local -n __o_sc=$1
  local __sc_h __sc_cmd
  shift
  for __sc_h in "$@"; do v_hostname "$__sc_h" >/dev/null 2>&1 || return 1; done
  __sc_cmd=$(printf '%q ' gemini-menu --role iran --yes domain set "$@")
  __o_sc=${__sc_cmd% }
}

# Keep the Iran side in sync: push over SSH when that works, otherwise print the command.
foreign_sync_iran() {  # the COMPLETE current list
  local cmd ip=$T_IP
  if [[ -z $ip ]]; then foreign_facts || true; ip=$T_IP; fi
  foreign_sync_cmd cmd "$@" || { ui_warn "the list contains an invalid hostname - not syncing"; return 0; }
  ui_blank
  ui_say "The Iran relay must accept the same hosts, or the missing ones are refused there."
  if v_ipv4 "$ip" >/dev/null 2>&1 && command -v ssh >/dev/null 2>&1 \
    && ssh -o BatchMode=yes -o ConnectTimeout=6 -- "root@$ip" true >/dev/null 2>&1; then
    if is_dry; then dry_say "SSH to $ip works: would run it there: $cmd"; return 0; fi
    if confirm "SSH to the Iran server ($ip) works. Push the new list there now?" y; then
      if ssh -o BatchMode=yes -- "root@$ip" "$cmd"; then ui_ok "Iran relay updated"; else ui_warn "the push failed - run this ON the Iran server:  $cmd"; fi
      return 0
    fi
  fi
  ui_say "Run this ON the Iran server (one line):"
  ui_say "  $cmd"
}


# ==== src/app/92-foreign-probes.sh ====
# shellcheck shell=bash
# 92-foreign-probes.sh - dashboard checks for the foreign (3X-UI) server, one probe per row.
# Same rules as the Iran probes: print LEVEL<TAB>BADGE<TAB>detail[<TAB>hint]; hints name real actions.

_fna() { printf 'off\tN/A\t%s\n' "$1"; }

pr_f_panel() {
  local xp
  if [[ -z $DB ]]; then
    printf 'fail\tNO DB\t3X-UI database not found\tPass --db /path/x-ui.db, or open the panel > Xray Configs and press Save once.\n'
    return 0
  fi
  xp=$(basename "${XRAY_BIN:-xray-linux}" | cut -c1-15)
  if systemctl is-active --quiet x-ui 2>/dev/null || pgrep -x "$xp" >/dev/null 2>&1; then
    printf 'ok\tRUNNING\tpanel running (db: %s)\n' "${DB#"$GM_ROOT"}"
  else
    printf 'fail\tDOWN\tthe panel is not running\tsystemctl status x-ui   then   systemctl restart x-ui\n'
  fi
}

pr_f_outbound() {
  [[ -n $DB ]] || { _fna "no database"; return 0; }
  if ! foreign_facts; then
    printf 'fail\tUNREADABLE\tcannot read the Xray template from the panel database\tCheck --db, and that the panel has saved its template once.\n'
    return 0
  fi
  if [[ $T_HAS == 1 ]]; then
    printf 'ok\tPRESENT\toutbound %s -> %s:%s (%s form)\n' "$TAG" "$T_IP" "$T_PORT" "$T_FORM"
  else
    printf 'fail\tMISSING\toutbound %s is not in the template\tSetup: press s (or: gemini-menu foreign setup)\n' "$TAG"
  fi
}

pr_f_relay() {
  foreign_facts && [[ $T_HAS == 1 ]] || { _fna "no outbound yet"; return 0; }
  if nc -z -w 3 "$T_IP" "$T_PORT" >/dev/null 2>&1; then
    printf 'ok\tREACHABLE\tIran relay %s:%s answers\n' "$T_IP" "$T_PORT"
  else
    printf 'fail\tUNREACHABLE\tIran relay %s:%s is NOT reachable\tThe path may be filtered, the relay down, or the Iran firewall blocks this server. On Iran: gemini-menu iran status\n' "$T_IP" "$T_PORT"
  fi
}

pr_f_routing() {
  foreign_facts || { _fna "template unreadable"; return 0; }
  case $T_STATE in
    on)
      if [[ $T_UDP != 1 ]]; then
        printf 'warn\tNO QUIC BLOCK\trouting is ON but the udp/443 (QUIC) block rule is missing\tSetup re-creates both rules: press s.\n'
      elif [[ $T_SCOPE == all ]]; then
        printf 'ok\tON\tall inbounds, %s hosts\n' "$T_NDOM"
      else
        printf 'ok\tON\t%s hosts for: %s\n' "$T_NDOM" "${T_SCOPE//,/ }"
      fi ;;
    off)     printf 'warn\tOFF\trules kept but they match nothing (Gemini goes out the normal way)\tRouting > Switch ON\n' ;;
    partial) printf 'warn\tINCONSISTENT\tthe two Gemini rules disagree (one on, one off/missing)\tRouting > Switch ON makes them consistent.\n' ;;
    *)       printf 'fail\tMISSING\tthe Gemini routing rules are not in the template\tSetup: press s.\n' ;;
  esac
}

pr_f_sniffing() {
  [[ -n $DB ]] || { _fna "no database"; return 0; }
  local n
  n=$(panel_py list "$DB" 2>/dev/null | grep -c . || true)
  if ((n > 0)); then
    printf 'warn\t%s BAD\t%s inbound(s) with bad sniffing: domain rules can miss\tSniffing > Fix selected inbounds\n' "$n" "$n"
  else
    printf 'ok\tOK\tevery enabled inbound sniffs tls+http\n'
  fi
}

pr_f_generated() {
  foreign_facts && [[ $T_HAS == 1 && -f $XRAY_DIR/config.json ]] || { _fna "nothing to compare"; return 0; }
  if grep -q "\"$TAG\"" "$XRAY_DIR/config.json"; then
    printf 'ok\tLOADED\tthe running Xray config contains %s\n' "$TAG"
  else
    printf 'warn\tNOT LOADED\tthe running Xray config does not contain %s yet\tThe panel needs a restart to load the template (Routing ON/OFF does that).\n' "$TAG"
  fi
}

pr_f_test() {
  local t res age
  t=$(state_get last_test_ts)
  res=$(state_get last_test_res)
  if [[ ! $t =~ ^[0-9]+$ ]]; then
    printf 'warn\tNEVER\tno end-to-end test has run yet\tEnd-to-end test: press 2.\n'
    return 0
  fi
  age=$(fmt_age $(($(now) - t)))
  if [[ $res == OK* ]]; then printf 'ok\tPASSED\t%s, %s\n' "$res" "$age"
  else printf 'fail\tFAILED\t%s, %s\tEnd-to-end test (2) shows which hop is broken.\n' "$res" "$age"; fi
}

foreign_register_probes() {
  probe_register panel     pr_f_panel     "3X-UI panel"
  probe_register outbound  pr_f_outbound  "Outbound $TAG"
  probe_register relay     pr_f_relay     "Iran relay"
  probe_register routing   pr_f_routing   "Gemini routing"
  probe_register sniffing  pr_f_sniffing  "Sniffing"
  probe_register generated pr_f_generated "Running config"
  probe_register test      pr_f_test      "End-to-end test"
}

foreign_status() {
  local badge xv
  probe_refresh
  case $(probe_worst) in
    ok)   ui_badge badge ok "HEALTHY" ;;
    warn) ui_badge badge warn "ATTENTION" ;;
    *)    ui_badge badge fail "PROBLEM" ;;
  esac
  xv=""
  if [[ -x ${XRAY_BIN:-} ]]; then xv=$("$XRAY_BIN" version 2>/dev/null | awk 'NR==1{print $2}'); fi
  ui_box_top "GEMINI $G_DOT SHECAN"
  ui_box_kv "Role" "${C_B}FOREIGN server (3X-UI)${C_0}  $badge"
  ui_box_probe "Panel" panel
  ui_box_probe "Outbound" outbound
  ui_box_probe "Iran relay" relay
  ui_box_probe "Routing" routing
  ui_box_probe "Sniffing" sniffing
  ui_box_probe "Running cfg" generated
  ui_box_probe "Last test" test
  ui_box_kv "Xray" "${xv:-unknown} ${C_DIM}(use the same version on the Iran server)${C_0}"
  ui_box_bottom
}

# ==== src/app/93-foreign-actions.sh ====
# shellcheck shell=bash
# 93-foreign-actions.sh - every foreign-side operation as an action (run through act_run).
#
# Conventions are the Iran ones: prompts re-ask and `b` cancels; an action that changes the panel
# goes through foreign_commit (typed confirmation, backup, compare-and-swap write, restart, verify,
# automatic restore on failure). Each action reads the template ONCE at its start.

# ================================================================== health ====================
foreign_act_health() {   # main shell (call:)
  ui_blank
  probe_refresh 1
  ui_rule "Health check"
  probe_report
  ui_blank
  case $(probe_worst) in
    ok)   ui_ok "Everything is fine." ;;
    warn) ui_warn "Works, but something needs attention (see the lines above)." ;;
    *)    ui_err "Something is broken (see what to do above)." ;;
  esac
}
foreign_cli_status() {
  probe_refresh 1
  probe_report
  case $(probe_worst) in ok) return 0 ;; warn) return 1 ;; *) return 2 ;; esac
}

# ================================================================== inputs ====================
# foreign_read_inputs: IRAN_IP / SS_PORT / key from flags or environment (act_fail on bad values)
foreign_read_inputs() {
  local kf=${KEY_FILE_ARG:-${FKEY_FILE:-}} mode key
  [[ -n $IRAN_IP ]] || act_fail "the Iran server's IP is required (--iran-ip IP or the IRAN_IP variable)"
  v_ipv4 "$IRAN_IP" || act_fail "IRAN_IP must be an IPv4 address ($IN_ERR)"
  v_port "$SS_PORT" || act_fail "invalid SS_PORT: $SS_PORT ($IN_ERR)"
  [[ -n $kf ]] || act_fail "the key file is required (--key-file FILE: the file written by the Iran setup)"
  [[ -r $kf ]] || act_fail "key file not readable: $kf"
  mode=$(stat -c %a "$kf")
  if [[ $mode != 600 && $mode != 400 ]]; then ui_warn "$kf has mode $mode; it holds a secret, consider chmod 600"; fi
  key=$(<"$kf")
  v_b64_bytes "$key" 16 || act_fail "the key in $kf is not base64 of 16 bytes ($SS_METHOD needs exactly that)"
  KEY_VAL=$IN_VALUE
}

# ================================================================== end-to-end test ===========
TEST_ROWS=()
foreign_test_prepare() {
  local t form kf=${KEY_FILE_ARG:-${FKEY_FILE:-}}
  need_cmds python3 nc curl
  if [[ -z $XRAY_DIR ]]; then find_xray; fi
  if [[ -z $IRAN_IP || -z $kf ]]; then
    need_cmds sqlite3
    if [[ -z $DB ]]; then find_db; fi
    ftpl_read_or_fail
    t=$(python3 - "$GM_TMP/template.orig.json" "$TAG" "$GM_TMP/outbound.json" <<'PY'
import json, sys
t = json.load(open(sys.argv[1]))
for o in t.get("outbounds", []):
    if o.get("tag") == sys.argv[2]:
        s = o.get("settings", {}); s = (s.get("servers") or [s])[0]
        print(s["address"], s["port"]); json.dump(o, open(sys.argv[3], "w")); sys.exit(0)
sys.exit(1)
PY
    ) || act_fail "no '$TAG' outbound in the panel template - run the setup first (menu: s)"
    IRAN_IP=${t% *}
    SS_PORT=${t#* }
  else
    foreign_read_inputs
    for form in servers flat; do
      P_FORM=$form P_IP=$IRAN_IP P_PORT=$SS_PORT P_KEY=$KEY_VAL P_METHOD=$SS_METHOD P_TAG=$TAG python3 - >"$GM_TMP/outbound.$form.json" <<'PY'
import json, os
e = os.environ
s = {"address": e["P_IP"], "port": int(e["P_PORT"]), "method": e["P_METHOD"], "password": e["P_KEY"]}
print(json.dumps({"tag": e["P_TAG"], "protocol": "shadowsocks", "settings": {"servers": [s]} if e["P_FORM"] == "servers" else s}))
PY
      python3 -c 'import json,sys;json.dump({"outbounds":[json.load(open(sys.argv[1]))]},open(sys.argv[2],"w"))' "$GM_TMP/outbound.$form.json" "$GM_TMP/ob-only.json"
      if panel_xray_test "$GM_TMP/ob-only.json"; then cp "$GM_TMP/outbound.$form.json" "$GM_TMP/outbound.json"; break; fi
    done
    [[ -s $GM_TMP/outbound.json ]] || act_fail "Xray rejected the outbound: $(xray_err | tr '\n' ' ')"
  fi
  NC_OK=0
  if nc -z -w 5 "$IRAN_IP" "$SS_PORT" >/dev/null 2>&1; then NC_OK=1; fi
  TEST_PORT=$(free_port)
  python3 - "$GM_TMP/outbound.json" "$TEST_PORT" "$GM_TMP/xray-test.log" >"$GM_TMP/test-config.json" <<'PY'
import json, sys
ob = json.load(open(sys.argv[1]))
print(json.dumps({"log": {"loglevel": "warning", "error": sys.argv[3]},
  "inbounds": [{"listen": "127.0.0.1", "port": int(sys.argv[2]), "protocol": "socks", "settings": {"auth": "noauth", "udp": False}}],
  "outbounds": [ob]}))
PY
  ( cd "$XRAY_DIR" && exec "$XRAY_BIN" run -config "$GM_TMP/test-config.json" >/dev/null 2>&1 ) &
  TEST_PID=$!
  act_defer kill "$TEST_PID"
  for _ in $(seq 1 20); do
    if nc -z 127.0.0.1 "$TEST_PORT" 2>/dev/null; then break; fi
    sleep 0.25
  done
  nc -z 127.0.0.1 "$TEST_PORT" 2>/dev/null || act_fail "the temporary Xray did not start: $(tail -n 3 "$GM_TMP/xray-test.log" 2>/dev/null)"
}

foreign_test_run() {  # foreign_test_run host...   all hosts probed in parallel
  local d i=0 f
  local -a pids=()
  rm -f "$GM_TMP"/res.*
  for d in "$@"; do
    (
      rc=0
      out=$(curl -sS -o /dev/null -w '%{http_code} %{time_total}' --max-time 15 -x "socks5h://127.0.0.1:$TEST_PORT" "https://$d/" 2>/dev/null) || rc=$?
      printf '%s\t%s\t%s\n' "$d" "$rc" "$out" >"$GM_TMP/res.$i"
    ) &
    pids+=($!)
    i=$((i + 1))
  done
  wait "${pids[@]}" 2>/dev/null || true
  kill "$TEST_PID" 2>/dev/null || true
  TEST_ROWS=()
  for ((f = 0; f < i; f++)); do TEST_ROWS+=("$(<"$GM_TMP/res.$f")"); done
}

foreign_test_report() {  # table + a plain-language verdict; sets TEST_OK / TEST_TOTAL
  local row d rc rest code t word badge ok=0 total=0 n403=0 verdict
  ui_blank
  ui_box_top "End-to-end test"
  for row in "${TEST_ROWS[@]}"; do
    IFS=$'\t' read -r d rc rest <<<"$row"
    code=${rest% *}
    t=${rest#* }
    total=$((total + 1))
    if [[ $rc == 0 && $code =~ ^[23] ]]; then
      ui_badge badge ok "OK"; ok=$((ok + 1))
    elif [[ $rc == 0 ]]; then
      ui_badge badge ok "OK $code"; ok=$((ok + 1))
      if [[ $code == 403 ]]; then n403=$((n403 + 1)); fi
    else
      ui_badge badge fail "FAIL"; t="-"
    fi
    ui_safe d "$d" 44
    ui_box_row "$(printf '%-44s' "$d") $badge ${C_DIM}${t}s${C_0}"
  done
  ui_box_bottom
  TEST_OK=$ok TEST_TOTAL=$total
  if [[ $NC_OK != 1 ]]; then
    verdict="BROKEN at: foreign -> Iran port ($IRAN_IP:$SS_PORT cannot be reached). The path may be filtered, the relay is down, or the Iran firewall does not allow this server. On Iran: gemini-menu iran status."
  elif ((ok == 0)); then
    verdict="BROKEN after the Iran port: it connects but nothing comes back. Most likely the Iran Shecan DNS is not working (registration lapsed) or Shecan cannot reach Google; a wrong key looks the same. On Iran: status, then register."
  elif ((ok < total)); then
    verdict="PARTLY WORKING: $((total - ok)) host(s) fail. Those hostnames may not be served by Shecan, or are misspelled. Remove them from the list or check them on Iran."
  elif ((n403 == total)); then
    verdict="Answers come back, but every one is 403: Shecan/Google may be refusing the Iran IP. On Iran: register this IP now."
  else
    verdict="The whole chain works: foreign -> Iran -> Shecan -> Google."
  fi
  ui_say "$verdict"
  state_set last_test_ts "$(now)"
  state_set last_test_res "$([[ $ok == "$total" && $total -gt 0 && $NC_OK == 1 ]] && echo "OK $ok/$total" || echo "FAIL $ok/$total ok")"
}

foreign_act_test() {  # foreign_act_test [quick]
  local -a hosts=()
  foreign_test_prepare
  mapfile -t hosts < <(foreign_domain_list)
  if [[ ${1:-} == quick || $QUICK == 1 ]]; then
    if [[ $ALL_DOMAINS != 1 ]]; then hosts=(gemini.google.com generativelanguage.googleapis.com); fi
  fi
  ui_note "temporary Xray on 127.0.0.1:$TEST_PORT, only outbound: $TAG -> $IRAN_IP:$SS_PORT (${#hosts[@]} hosts, in parallel)"
  foreign_test_run "${hosts[@]}"
  foreign_test_report
  # a closed relay port fails the test even if some probe got an answer from somewhere else
  if [[ $NC_OK != 1 ]]; then act_fail "the Iran relay port $IRAN_IP:$SS_PORT is not reachable"; fi
  ((TEST_OK == TEST_TOTAL)) || act_fail "$((TEST_TOTAL - TEST_OK)) of $TEST_TOTAL probes failed"
}

# ================================================================== routing, scope ============
foreign_act_routing() {  # foreign_act_routing on|off
  [[ ${1:-} == on || ${1:-} == off ]] || act_fail "routing: use on | off (got '${1:-nothing}')" 2
  P_STATE=$1 foreign_tpl_action toggle
}

foreign_scope_apply() { P_TAGS="$*" foreign_tpl_action scope; }

foreign_act_scope() {  # foreign_act_scope [all | TAG...]   (no argument: pick interactively)
  local line tag port remark proto i total
  local -a tags=() labels=() sel=() chosen=() picked=()
  need_panel
  foreign_facts || act_fail "cannot read the template"
  [[ $T_STATE != missing ]] || act_fail "the Gemini rules are not in the template yet - run the setup first (menu: s)"
  if (($# > 0)); then
    if [[ $1 == all ]]; then foreign_scope_apply; else foreign_scope_apply "$@"; fi
    return 0
  fi
  while IFS=$'\x1f' read -r tag port remark proto; do
    tags+=("$tag")
    labels+=("$tag  :$port  ${remark:-(no name)}  [$proto]")
    if [[ $T_SCOPE == all || ",$T_SCOPE," == *",$tag,"* ]]; then sel+=(1); else sel+=(0); fi
  done < <(panel_py inbounds "$DB")
  total=${#tags[@]}
  ((total > 0)) || act_fail "no enabled client inbounds found in the panel"
  ((IN_OK)) || act_fail "choosing inbounds needs a terminal (or: scope all | scope set TAG...)"
  pick_many chosen "Scope: who uses $TAG (ticked inbounds send the Gemini hosts to Iran)" labels sel || act_cancel
  for i in "${chosen[@]}"; do picked+=("${tags[i]}"); done
  ((${#picked[@]} > 0)) || act_fail "nothing ticked - to switch Gemini routing off use Routing > OFF"
  if ((${#picked[@]} == total)); then foreign_scope_apply; else foreign_scope_apply "${picked[@]}"; fi
}

# ================================================================== domain list ===============
foreign_act_domains_list() { need_panel; foreign_domain_list | nl -w2 -s'. ' | sed 's/^/  /'; }

foreign_domains_apply() { P_DOMAINS="$*" foreign_tpl_action domains; }   # the COMPLETE new list

foreign_act_domain_add() {
  local h=${1:-} d
  local -a cur=()
  need_panel
  if [[ -z $h ]]; then
    prompt_hostname h "Hostname to add (e.g. gemini.google.com)" || act_cancel
  else
    v_hostname "$h" || act_fail "not a valid hostname: $h ($IN_ERR)"
    h=$IN_VALUE
  fi
  mapfile -t cur < <(foreign_domain_list)
  for d in "${cur[@]}"; do
    if [[ $d == "$h" ]]; then ui_ok "$h is already in the list"; return 0; fi
  done
  foreign_domains_apply "${cur[@]}" "$h"
  foreign_sync_iran "${cur[@]}" "$h"
}

foreign_act_domain_remove() {
  local h=${1:-} d
  local -a cur=() keep=()
  need_panel
  mapfile -t cur < <(foreign_domain_list)
  if [[ -z $h ]]; then
    ((${#cur[@]} > 0)) || act_cancel "the list is empty"
    prompt_choice h "Remove which host (number or name)" "" "${cur[@]}" || act_cancel
  else
    v_hostname "$h" || act_fail "not a valid hostname: $h ($IN_ERR)"
    h=$IN_VALUE
  fi
  for d in "${cur[@]}"; do if [[ $d != "$h" ]]; then keep+=("$d"); fi; done
  if ((${#keep[@]} == ${#cur[@]})); then ui_ok "$h is not in the list"; return 0; fi
  foreign_domains_apply "${keep[@]}"
  foreign_sync_iran "${keep[@]}"
}

foreign_act_domain_set() {
  local d
  local -a list=()
  need_panel
  for d in "$@"; do
    v_hostname "$d" || act_fail "not a valid hostname: $d ($IN_ERR)"
    list+=("$IN_VALUE")
  done
  foreign_domains_apply "${list[@]}"
  foreign_sync_iran "${list[@]}"
}

foreign_act_sync_iran() {
  local -a l=()
  need_panel
  mapfile -t l < <(foreign_domain_list)
  foreign_sync_iran "${l[@]}"
}

# ================================================================== sniffing ==================
foreign_act_sniff_audit() {
  need_cmds sqlite3 python3
  if [[ -z $DB ]]; then find_db; fi
  ui_note "Domain rules need the destination domain, so the inbound must sniff (tls/http) and must"
  ui_note "not use routeOnly: with routeOnly the connection to $TAG would still carry an IP and the"
  ui_note "Iran relay (which only accepts the listed domains) would refuse it."
  panel_py audit "$DB" "$GM_TMP/sniff.count"
  SNIFF_FLAGGED=$(<"$GM_TMP/sniff.count")
}
SNIFF_FLAGGED=0

foreign_act_sniff_fix() {  # foreign_act_sniff_fix [ids|all]   (no argument: pick interactively)
  local ids=${1:-} iid remark port proto probs i
  local -a all=() labels=() sel=() chosen=() pick=()
  need_panel
  while IFS=$'\x1f' read -r iid remark port proto probs; do
    all+=("$iid")
    labels+=("$remark :$port $proto - $probs")
    sel+=(1)
  done < <(panel_py list "$DB")
  if ((${#all[@]} == 0)); then ui_ok "every enabled inbound already sniffs correctly - nothing to fix"; return 0; fi
  if [[ -z $ids ]]; then
    ((IN_OK)) || act_fail "choosing inbounds needs a terminal (or: sniffing fix all | sniffing fix ID,ID)"
    pick_many chosen "These inbounds have a problem: tick the ones to fix" labels sel || act_cancel
    ((${#chosen[@]} > 0)) || act_cancel "nothing ticked"
    for i in "${chosen[@]}"; do pick+=("${all[i]}"); done
    ids=$(IFS=,; echo "${pick[*]}")
  elif [[ $ids != all ]]; then
    [[ $ids =~ ^[0-9]+(,[0-9]+)*$ ]] || act_fail "sniffing fix: use all or a comma-separated list of inbound ids (got '$ids')" 2
  fi
  ui_say "Will set on inbound id(s) $ids: sniffing ON with http+tls, routeOnly off, metadataOnly off."
  ui_note "(The old values are saved in the backup, so Backups > restore can undo it.)"
  ftpl_read_or_fail
  cp "$GM_TMP/template.orig.json" "$GM_TMP/new.json"
  echo 0 >"$GM_TMP/new.json.changed"
  COMMIT_FIX_IDS=$ids
  foreign_commit "$GM_TMP/new.json"
}

# ================================================================== learn mode ================
learn_log_path() {  # resolved access-log path from T_ACCESS, or empty when logging is off
  local a=$T_ACCESS c
  case $a in "" | none | __unset__) return 0 ;; esac
  if [[ $a == /* ]]; then printf '%s' "$a"; return 0; fi
  for c in "$XRAY_DIR/$a" "$(dirname "$XRAY_DIR")/$a" "$XRAY_DIR/../$a"; do
    if [[ -f $c ]]; then printf '%s' "$c"; return 0; fi
  done
  printf '%s' "$XRAY_DIR/$a"
}

# learn_capture SECONDS OUTFILE FILTER : hostnames seen in the access log during the next SECONDS seconds.
# Only strict DNS names survive (letters, digits, hyphen, dots; <= 253 chars): the log is written by
# clients, so anything else - shell metacharacters, escape sequences, IPs - is dropped here, counted,
# and never shown or used. (Findings 4 and 10.)
learn_capture() {
  local secs=$1 out=$2 filt=$3 size0 left
  size0=$(stat -c %s "$LEARN_PATH" 2>/dev/null || echo 0)
  for ((left = secs; left > 0; left--)); do
    if ((UI_TTY)); then printf '\r  capturing...  %3ds left ' "$left"; fi
    sleep 1
  done
  if ((UI_TTY)); then printf '\r  capture finished.            \n'; else ui_note "capture finished"; fi
  python3 - "$LEARN_PATH" "$size0" "$filt" >"$out" <<'PY'
import os, re, sys
path, off, filt = sys.argv[1], int(sys.argv[2]), sys.argv[3]
try:
    size = os.path.getsize(path)
    f = open(path, "rb")
    f.seek(off if size >= off else 0)          # log rotated/truncated: read from the start
    data = f.read().decode("utf-8", "replace")
except OSError:
    data = ""
rx = re.compile(r"accepted (?:tcp|udp):([^:\s\]]+):(\d+)")
ip = re.compile(r"^\d+\.\d+\.\d+\.\d+$")
dns = re.compile(r"^(?=.{1,253}$)[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$")
seen, dropped = {}, 0
for line in data.splitlines():
    if filt and filt not in line:
        continue
    m = rx.search(line)
    if not m:
        continue
    h = m.group(1).lower()
    if ip.match(h) or ":" in h:
        continue
    if not dns.match(h):
        dropped += 1
        continue
    seen[h] = seen.get(h, 0) + 1
for h, n in sorted(seen.items()):
    print("%s\t%d" % (h, n))
if dropped:
    sys.stderr.write("%d line(s) with a malformed hostname were ignored\n" % dropped)
PY
}

foreign_log_restore() {  # put log.access back to what it was before learn mode switched it on
  local orig
  orig=$(state_get learn_orig_access)
  if [[ -z $orig ]]; then ui_ok "the access log was not changed by learn mode"; return 0; fi
  case $orig in __unset__ | none) orig=none ;; esac      # (fixed: the old code wrote the literal text "__unset__")
  ftpl_read_or_fail
  P_ACCESS=$orig py_tpl logaccess "$GM_TMP/template.orig.json" "$GM_TMP/new.json" | sed 's/^/  /'
  foreign_commit "$GM_TMP/new.json"
  state_set learn_orig_access ""
}
foreign_act_learn_restore() { need_panel; foreign_log_restore; }

foreign_act_learn() {
  local turned_on=0 idle=20 active=40 filt="" i h n
  local -a labels=() sel=() hosts=() chosen=() picked=() cur=()
  need_panel
  ftpl_read_or_fail
  eval "$(py_tpl inspect "$GM_TMP/template.orig.json")"
  [[ $T_HAS == 1 ]] || act_fail "$TAG is not set up yet - run the setup first (menu: s)"
  ((IN_OK)) || act_fail "learn mode needs a terminal (it walks you through using the phone app)"
  LEARN_PATH=$(learn_log_path)
  if [[ -z $LEARN_PATH ]]; then
    ui_say "The panel's access log is OFF (log.access = ${T_ACCESS/__unset__/unset}); learn mode reads it."
    ui_say "Turning it on changes the template and restarts the panel (users are dropped for a few seconds)."
    confirm "Turn the access log on for now?" y || act_cancel
    LEARN_PATH=$GM_ROOT/var/log/gemini-menu-access.log
    if ! is_dry; then mkdir -p "$(dirname "$LEARN_PATH")"; : >>"$LEARN_PATH"; fi
    state_set learn_orig_access "${T_ACCESS:-none}"
    P_ACCESS=$LEARN_PATH py_tpl logaccess "$GM_TMP/template.orig.json" "$GM_TMP/new.json" | sed 's/^/  /'
    foreign_commit "$GM_TMP/new.json"
    turned_on=1
    act_partial "the panel's access log is ON (learn mode switched it on)"
    act_tip "switch it back with: gemini-menu foreign learn-restore"
  fi
  if is_dry; then dry_say "would capture hostnames twice from $LEARN_PATH and offer the new ones"; return 0; fi
  ui_say "Access log: $LEARN_PATH"
  ui_say "The log holds ALL users' traffic. To count only your phone, type part of its line"
  ui_say "(your client's email/name in the panel, or the phone's IP). Empty = count everything."
  IN_ALLOW_EMPTY=1 prompt_valid filt "Filter text" "" v_nonempty || act_cancel
  prompt_int idle "Seconds to capture with the phone IDLE" 1 600 "$idle" || act_cancel
  prompt_int active "Seconds to capture while you USE Gemini" 1 600 "$active" || act_cancel
  ui_blank
  ui_step "STEP 1 of 2: put the phone on the VPN, close Gemini and leave it alone."
  in_read _ "  Press Enter to start the idle capture... " || act_cancel
  learn_capture "$idle" "$GM_TMP/learn.idle" "$filt"
  ui_step "STEP 2 of 2: now open the Gemini app and use it (chat, upload, voice...)."
  in_read _ "  Press Enter, then start using Gemini right away... " || act_cancel
  learn_capture "$active" "$GM_TMP/learn.active" "$filt"

  python3 - "$GM_TMP/learn.idle" "$GM_TMP/learn.active" "$T_DOMAINS" "${LEARN_SKIP_HOSTS[*]}" "${LEARN_SKIP_SUFFIX[*]}" >"$GM_TMP/learn.new" <<'PY'
import sys
def load(p):
    d = {}
    for line in open(p):
        h, n = line.rstrip("\n").split("\t")
        d[h] = int(n)
    return d
idle, active = load(sys.argv[1]), load(sys.argv[2])
have, skip, suf = set(sys.argv[3].split()), set(sys.argv[4].split()), sys.argv[5].split()
for h, n in sorted(active.items(), key=lambda kv: (-kv[1], kv[0])):
    if h in idle or h in have or h in skip:
        continue
    if any(h == s or h.endswith("." + s) for s in suf):
        continue
    print("%s\t%d" % (h, n))
PY
  while IFS=$'\t' read -r h n; do
    v_hostname "$h" || continue                  # belt and braces: the same validator the typed path uses
    hosts+=("$IN_VALUE")
    labels+=("$IN_VALUE   ($n request(s))")
    sel+=(0)
  done <"$GM_TMP/learn.new"
  if ((${#hosts[@]} == 0)); then
    ui_blank
    ui_note "No new hostnames appeared in step 2 (idle traffic, hosts already routed and known"
    ui_note "background hosts are hidden). Is sniffing on, and did the phone really use the VPN?"
  else
    # cancelling here ends the action (pick_many returns 10): no "ghost ticks" get applied
    pick_many chosen "New hostnames: tick the ones that belong to Gemini (unsure? leave them out)" labels sel || act_cancel
    for i in "${chosen[@]}"; do picked+=("${hosts[i]}"); done
    if ((${#picked[@]} > 0)); then
      mapfile -t cur < <(foreign_domain_list)
      ui_say "Adding: ${picked[*]}"
      foreign_domains_apply "${cur[@]}" "${picked[@]}"
      foreign_sync_iran "${cur[@]}" "${picked[@]}"
    fi
  fi
  if ((turned_on)); then
    if confirm "Turn the access log back off? This restarts the panel again." y; then
      foreign_log_restore
      : >"$ACT_STATE"
    else
      ui_note "left ON. Switch it off later with: gemini-menu foreign learn-restore"
    fi
  fi
}

# ================================================================== backups ===================
foreign_bk_summary() {
  local d=$1 s=""
  if [[ -f $d/template.orig.json ]]; then s+="template "; fi
  if [[ -f $d/sniffing.orig.json ]]; then s+="sniffing "; fi
  if [[ -f $d/x-ui.db ]]; then s+="db-copy "; fi
  if [[ -f $d/foreign.manifest.rolledback ]]; then s+="[undone]"; fi
  echo "${s:-(empty)}"
}

foreign_act_backup_diff() {  # DIR
  need_cmds python3
  [[ -f $1/template.orig.json ]] || { ui_note "This backup holds no template copy."; return 0; }
  if [[ -z $DB ]]; then find_db; fi
  ftpl_read_or_fail
  ui_note "Restoring this backup would change the CURRENT template like this:"
  P_IN2=$1/template.orig.json py_tpl diff "$GM_TMP/template.orig.json" | sed 's/^/    /'
}

foreign_act_backup_restore() {  # DIR
  local d=$1
  need_panel
  [[ -f $d/template.orig.json ]] || act_fail "this backup holds no template copy"
  ftpl_read_or_fail
  P_IN2=$d/template.orig.json P_OUT=$GM_TMP/new.json py_tpl diff "$GM_TMP/template.orig.json" "$GM_TMP/new.json" | sed 's/^/  /'
  COMMIT_RESTORE_FILE=""
  if [[ -f $d/sniffing.orig.json ]] && foreign_ask_optional "This backup also saved sniffing values. Restore them too?"; then
    COMMIT_RESTORE_FILE=$d/sniffing.orig.json
  fi
  foreign_commit "$GM_TMP/new.json"
}

# an optional extra: --yes means "skip it" (only an explicit answer at a terminal enables it)
foreign_ask_optional() {
  if [[ $GM_YES == 1 ]]; then return 1; fi
  confirm "$1" n
}

# ================================================================== revert ====================
foreign_act_revert() {
  local first="" d restore_full=0
  need_panel
  ftpl_read_or_fail
  if ! py_tpl revert "$GM_TMP/template.orig.json" "$GM_TMP/new.json" | sed 's/^/  /'; then act_fail "could not compute the change"; fi
  # the template as it was before this tool first touched it = the oldest backup copy
  for d in $(bk_dirs | sort); do
    if [[ -f $d/template.orig.json ]]; then first=$d; break; fi
  done
  if [[ -n $first ]]; then
    ui_say "Compared with the template from before this tool first ran ($(basename "$first")):"
    P_IN2=$first/template.orig.json py_tpl diff "$GM_TMP/new.json" | sed 's/^/    /'
    if ! P_IN2=$first/template.orig.json py_tpl diff "$GM_TMP/new.json" | grep -q '^= identical'; then
      if foreign_ask_optional "Restore that ORIGINAL template completely (drops template edits made since)?"; then restore_full=1; fi
    fi
  fi
  if ((restore_full)); then
    cp "$first/template.orig.json" "$GM_TMP/new.json"
    echo 1 >"$GM_TMP/new.json.changed"
  fi
  # sniffing values: the oldest saved value per inbound wins
  python3 - "$BACKUP_ROOT" "$GM_TMP/sniff.merge.json" <<'PY'
import glob, json, os, sys
merged = {}
for p in sorted(glob.glob(os.path.join(sys.argv[1], "*", "sniffing.orig.json"))):
    for k, v in json.load(open(p)).items():
        merged.setdefault(k, v)
json.dump(merged, open(sys.argv[2], "w"))
PY
  COMMIT_RESTORE_FILE=""
  if [[ $(python3 -c 'import json,sys;print(len(json.load(open(sys.argv[1]))))' "$GM_TMP/sniff.merge.json") -gt 0 ]]; then
    ui_say "Sniffing values saved by this tool will be put back as well."
    COMMIT_RESTORE_FILE=$GM_TMP/sniff.merge.json
  fi
  foreign_commit "$GM_TMP/new.json"
}

# ================================================================== rollback (undo a run) =====
foreign_act_rollback() {  # foreign_act_rollback [DIR]   undo the newest run that changed something
  local d=${1:-$BACKUP_DIR_ARG} cand rc=0 exp
  iran_require_root
  if [[ -z $d ]]; then
    while IFS= read -r cand; do
      if [[ -s $cand/$MANIFEST ]]; then d=$cand; break; fi
    done < <(bk_dirs)
  fi
  [[ -n $d && -s $d/$MANIFEST ]] || act_fail "no $MANIFEST found under $BACKUP_ROOT (nothing to roll back)"
  BK=$d
  DB=$(awk -F'\t' '$1=="DB"{print $2}' "$BK/$MANIFEST")
  XRAY_BIN=$(awk -F'\t' '$1=="XRAY"{print $2}' "$BK/$MANIFEST")
  XRAY_DIR=$(dirname "$XRAY_BIN")
  RESTART_CMD=$(awk -F'\t' '$1=="RESTART"{print $2}' "$BK/$MANIFEST")
  ui_say "rolling back run $(basename "$BK") (db: $DB)"
  if is_dry; then
    dry_say "would restore $([[ $RESTORE_FULL_DB == 1 ]] && echo 'the full DB copy' || echo 'the saved template/sniffing') and run: $RESTART_CMD"
    return 0
  fi
  ui_warn "This restarts the panel and drops ALL user connections for a few seconds."
  confirm "Roll back now?" n || act_cancel
  if [[ $RESTORE_FULL_DB == 1 ]]; then
    [[ $RESTART_CMD == "systemctl restart x-ui" ]] || act_fail "--restore-full-db needs the default systemd setup (x-ui.service)"
    ui_warn "the WHOLE database copy is restored: traffic counters and clients changed since then are lost"
    confirm_typed_force "Replace the live panel database with the backup copy?" yes || act_cancel
    must systemctl stop x-ui
    cp -p "$BK/x-ui.db" "$DB"
    rm -f "$DB-wal" "$DB-shm"
    must systemctl start x-ui
  else
    exp=$BK/template.new.json
    [[ -f $exp ]] || exp=-
    panel_py restore "$DB" "$BK" "$exp" || rc=$?
    if ((rc == 3)); then
      ui_warn "the template in the panel is NOT what this run wrote: it was edited afterwards."
      ui_note "Restoring the saved one would discard those later edits."
      confirm_typed_force "Restore the saved template anyway and lose the later edits?" yes || act_cancel
      panel_py restore "$DB" "$BK" - || act_fail "the restore failed"
    elif ((rc != 0)); then
      act_fail "the restore failed (exit $rc)"
    fi
    restart_panel || act_fail "restarting the panel failed (command: $RESTART_CMD)"
  fi
  if wait_xray "$(expect_after_restore "$BK")"; then
    ui_ok "rollback done: the generated Xray config matches the restored template"
  else
    ui_warn "could not confirm the restore from the generated config - check: systemctl status x-ui"
  fi
  mv -f "$BK/$MANIFEST" "$BK/$MANIFEST.rolledback"
}

# ==== src/app/94-foreign-setup.sh ====
# shellcheck shell=bash
# 94-foreign-setup.sh - patch the 3X-UI Xray template: outbound ir-gemini + two routing rules.
#
#   gemini-menu foreign setup [--iran-ip IP --key-file FILE --ss-port N --db PATH --xray-bin PATH --fix-sniffing]
#
# Missing inputs are asked for interactively. The patch removes the old gemini-shecan outbound and
# gemini-related balancers; appends ir-gemini last (the default outbound is unchanged); inserts two rules
# right after the "bittorrent -> blocked" rule: udp/443 for the domains -> blocked (QUIC falls back to
# TCP) and the domains -> ir-gemini. It refuses to guess if that rule is missing. The patched template
# is validated with the panel's own Xray, written with compare-and-swap, and a failed restart puts the
# previous template back automatically.

KEY_VAL=""

foreign_act_setup() {
  local form ok="" cur kf
  need_cmds sqlite3 python3 nc base64
  iran_require_root
  if [[ -z $DB ]]; then locate_db || true; fi
  if [[ -n $DB ]]; then foreign_facts >/dev/null 2>&1 || true; fi

  if [[ -z $IRAN_IP ]]; then
    ((IN_OK)) || act_fail "the Iran server's IP is required (--iran-ip IP or the IRAN_IP variable)"
    ui_say "You need the Iran relay's IP and its key file."
    ui_note "(On Iran: 'gemini-menu iran info' prints the two commands that bring the key file here.)"
    prompt_ipv4 IRAN_IP "Iran server IPv4 address" "${T_IP:-}" || act_cancel
  fi
  if [[ -z ${KEY_FILE_ARG:-${FKEY_FILE:-}} ]]; then
    ((IN_OK)) || act_fail "the key file is required (--key-file FILE: the file written by the Iran setup)"
    prompt_file kf "Path of the key file on THIS server" "/root/gemini-ss.key" || act_cancel
    KEY_FILE_ARG=$kf
  fi
  foreign_read_inputs

  act_step "Check the path foreign -> Iran"
  ui_note "checking $IRAN_IP:$SS_PORT ..."
  if nc -z -w 5 "$IRAN_IP" "$SS_PORT" >/dev/null 2>&1; then
    NC_OK=1
    ui_ok "$IRAN_IP:$SS_PORT is reachable"
  else
    NC_OK=0
    act_fail "$IRAN_IP:$SS_PORT is not reachable from this server. The foreign -> Iran path may be filtered, the relay may not be running, or the Iran firewall does not allow this server's IP. Fix that first (Iran side: gemini-menu iran status / foreign-ip), then re-run."
  fi

  act_step "Locate the panel"
  if [[ -z $DB ]]; then find_db; else ui_ok "3X-UI database: $DB"; fi
  if [[ -z $XRAY_DIR ]]; then find_xray; fi
  ftpl_read_or_fail

  act_step "Patch the template"
  cur=$(eval "$(py_tpl inspect "$GM_TMP/template.orig.json")"; echo "$T_DOMAINS")
  if [[ -n $cur ]]; then
    read -r -a GEMINI_DOMAINS <<<"$cur"
    ui_ok "keeping the current domain list (${#GEMINI_DOMAINS[@]} hosts)"
  fi
  if panel_xray_test "$GM_TMP/template.orig.json"; then
    ui_ok "the original template passes 'xray -test'"
  else
    ui_warn "the ORIGINAL template does not pass 'xray -test' in this environment: $(xray_err | tr '\n' ' ')"
  fi
  for form in servers flat; do
    P_FORM=$form P_IP=$IRAN_IP P_PORT=$SS_PORT P_KEY=$KEY_VAL P_METHOD=$SS_METHOD P_DOMAINS="${GEMINI_DOMAINS[*]}" \
      py_tpl patch "$GM_TMP/template.orig.json" "$GM_TMP/template.$form.json" >"$GM_TMP/patch.$form.log" \
      || act_fail "$(cat "$GM_TMP/patch.$form.log" 2>/dev/null) cannot patch this template"
    if panel_xray_test "$GM_TMP/template.$form.json"; then ok=$form; break; fi
    ui_warn "Xray rejected the '$form' outbound form: $(xray_err | tr '\n' ' ')"
  done
  [[ -n $ok ]] || act_fail "Xray rejected the patched template in both outbound forms; nothing was written"
  sed 's/^/  /' "$GM_TMP/patch.$ok.log"
  ui_ok "patched template validated with the panel's Xray (outbound form: $ok)"

  act_step "Sniffing audit (report only unless --fix-sniffing)"
  foreign_act_sniff_audit
  COMMIT_FIX_IDS=""
  if [[ $FIX_SNIFFING == 1 && $SNIFF_FLAGGED -gt 0 ]]; then COMMIT_FIX_IDS=all; fi
  if [[ $SNIFF_FLAGGED -gt 0 && $FIX_SNIFFING == 0 ]]; then
    ui_warn "$SNIFF_FLAGGED inbound(s) need sniffing: not changed. Sniffing > Fix selected inbounds (or --fix-sniffing)."
  fi

  foreign_commit "$GM_TMP/template.$ok.json"
  if ! is_dry; then role_set foreign; fi
  ui_blank
  ui_say "Next: gemini-menu foreign test      (checks foreign -> Iran -> Shecan -> Google)"
  ui_say "Undo: gemini-menu foreign rollback"
}

# ==== src/app/95-foreign-screens.sh ====
# shellcheck shell=bash
# 95-foreign-screens.sh - the foreign menu, as data.

foreign_en_panel() {
  if [[ -n $DB ]]; then return 0; fi
  MENU_WHY="the 3X-UI database was not found - pass --db, or open the panel > Xray Configs and press Save once"
  return 1
}

foreign_routing_card() {
  local badge
  foreign_facts >/dev/null 2>&1 || true
  case $T_STATE in
    on)      ui_badge badge ok ON ;;
    off)     ui_badge badge warn OFF ;;
    partial) ui_badge badge warn INCONSISTENT ;;
    *)       ui_badge badge fail MISSING ;;
  esac
  ui_box_top "Gemini routing"
  ui_box_kv "State" "$badge  scope: $T_SCOPE, $T_NDOM hosts"
  ui_box_row "${C_DIM}OFF keeps both rules but makes them match nothing: Gemini goes out the normal way.${C_0}"
  ui_box_row "${C_DIM}Each switch restarts the panel (users are dropped for a few seconds).${C_0}"
  ui_box_bottom
}

foreign_domains_card() {
  local d i=0
  ui_box_top "Routed hosts"
  while IFS= read -r d; do
    i=$((i + 1))
    ui_safe d "$d" $((UI_W - 12))
    ui_box_row "${C_DIM}$(printf '%2d.' "$i")${C_0} $d"
  done < <(foreign_domain_list 2>/dev/null || true)
  ui_box_row "${C_DIM}the Iran relay must accept the same hosts (Push list to Iran)${C_0}"
  ui_box_bottom
}

foreign_sniffing_card() {
  ui_box_top "Sniffing"
  ui_box_row "${C_DIM}domain rules only work if the inbound sniffs tls/http and routeOnly is off${C_0}"
  ui_box_bottom
  if [[ -n $DB ]]; then panel_py audit "$DB" "$GM_TMP/sniff.count" 2>/dev/null || true; fi
}

# ---- backups (dynamic) ------------------------------------------------------------------------------------
FOREIGN_SEL_BK=""
foreign_bk_open() { FOREIGN_SEL_BK=$1; MENU_STACK+=(f_bkdetail); }
foreign_backups_build() {
  local i=0 d
  menu_reset f_backups
  while IFS= read -r d; do
    i=$((i + 1))
    if ((i > 20)); then break; fi
    menu_item f_backups "$i" "$(basename "$d")" "$(foreign_bk_summary "$d")" "call:foreign_bk_open $d"
  done < <(bk_dirs)
}
foreign_backups_card() {
  ui_box_top "Backups ($BACKUP_ROOT)"
  if [[ -z $(bk_dirs) ]]; then ui_box_row "${C_DIM}no backups yet: created the first time something changes${C_0}"; fi
  ui_box_row "${C_DIM}the OLDEST backup is the template from before this tool first ran${C_0}"
  ui_box_bottom
}
foreign_bkdetail_build() {
  menu_reset f_bkdetail
  menu_item f_bkdetail 1 "Diff against the current template" "what restoring would change" "view:foreign_act_backup_diff $FOREIGN_SEL_BK"
  menu_item f_bkdetail 2 "Restore it" "typed confirmation, panel restarts" "action:foreign_act_backup_restore $FOREIGN_SEL_BK"
}
foreign_bkdetail_card() {
  ui_box_top "Backup $(basename "$FOREIGN_SEL_BK")"
  ui_box_kv "Contains" "$(foreign_bk_summary "$FOREIGN_SEL_BK")  (the state BEFORE that run)"
  ui_box_bottom
}

foreign_screens() {
  menu_screen main "Foreign server" foreign_status
  menu_item main 1 "Health check"          "live checks, what to do"      call:foreign_act_health
  menu_item main 2 "End-to-end test"       "foreign > Iran > Shecan > Google" action:foreign_act_test foreign_en_panel
  menu_item main 3 "Gemini routing"        "switch ON / OFF"              screen:f_routing foreign_en_panel
  menu_item main 4 "Scope: which inbounds" "who uses the relay"           action:foreign_act_scope foreign_en_panel
  menu_item main 5 "Domains"               "hosts routed to Iran"         screen:f_domains foreign_en_panel
  menu_item main 6 "Learn mode (phone app)" "find hosts the app uses"     action:foreign_act_learn foreign_en_panel
  menu_item main 7 "Sniffing"              "audit / fix inbounds"         screen:f_sniffing foreign_en_panel
  menu_item main 8 "Backups"               "diff, restore"                screen:f_backups foreign_en_panel
  menu_item main 9 "Revert everything"     "remove ir-gemini + its rules" action:foreign_act_revert foreign_en_panel
  menu_item main s "Setup / re-run setup"  "patch the panel template"     action:foreign_act_setup

  menu_screen f_routing "Routing" foreign_routing_card
  menu_item f_routing 1 "Switch ON"  "" "action:foreign_act_routing on"
  menu_item f_routing 2 "Switch OFF" "" "action:foreign_act_routing off"

  menu_screen f_domains "Domains" foreign_domains_card
  menu_item f_domains 1 "Add a hostname"       "offers to sync Iran"       action:foreign_act_domain_add
  menu_item f_domains 2 "Remove a hostname"    "pick by number or name"    action:foreign_act_domain_remove
  menu_item f_domains 3 "Push the list to Iran" "ssh, or prints the command" action:foreign_act_sync_iran

  menu_screen f_sniffing "Sniffing" foreign_sniffing_card
  menu_item f_sniffing 1 "Fix selected inbounds" "old values are saved in the backup" action:foreign_act_sniff_fix
  menu_item f_sniffing 2 "Run the audit again"   "" view:foreign_act_sniff_audit

  menu_screen f_backups "Backups" foreign_backups_card foreign_backups_build
  menu_screen f_bkdetail "Backup" foreign_bkdetail_card foreign_bkdetail_build
}

# ==== src/app/96-foreign-cli.sh ====
# shellcheck shell=bash
# 96-foreign-cli.sh - gemini-menu foreign <command> ...   (call foreign_cli as its own statement)
#   0 ok | 1 health: warnings | 2 health: broken / usage | 10 cancelled | 130 interrupted | other: failed

foreign_usage() {
  cat <<EOF2
gemini-menu foreign <command> [flags]

  (no command)            interactive menu
  status                  health check (exit 0 healthy, 1 warnings, 2 broken)
  setup | apply           patch the 3X-UI template (--iran-ip --key-file --ss-port --db --xray-bin --fix-sniffing)
  test [--quick]          end-to-end test, one row per host (--all-domains probes every host)
  routing on|off|status   switch the two Gemini rules without deleting them
  scope all | set TAG... | pick | list     (pick = choose the inbounds interactively)
  domain list|add H|remove H|set H...    (offers to sync the Iran relay)
  sync-iran               push the current host list to the Iran relay
  learn                   capture hostnames used by the phone app      learn-restore   undo its access-log switch
  sniffing audit|fix [IDS|all]            audit  = alias for 'sniffing audit'
  backups [list|diff N|restore N]
  revert                  remove ir-gemini + its rules (restores the pre-tool template)
  rollback [--backup-dir D] [--restore-full-db]    undo the newest run that changed something
  install-self            install this file as /usr/local/bin/gemini-menu
EOF2
}

foreign_cli_backup_dir() {
  local n=${1:-} d
  v_int_range "$n" 1 999 || { ui_err "backup number: $IN_ERR"; return 2; }
  d=$(bk_dirs | sed -n "${n}p")
  if [[ -z $d ]]; then ui_err "no backup number $n (see: backups list)"; return 2; fi
  printf '%s' "$d"
}

foreign_cli() {
  local c=${1:-status} d i=0
  shift || true
  case $c in
    status | health) foreign_cli_status; return $? ;;
    setup | apply)   act_run "Setup" foreign_act_setup; return $? ;;
    test)
      if [[ ${1:-} == --quick ]]; then QUICK=1; fi
      act_run "End-to-end test" foreign_act_test; return $? ;;
    routing)
      case ${1:-status} in
        on | off) act_run "Gemini routing $1" foreign_act_routing "$1" ;;
        status)
          if foreign_facts; then ui_say "Gemini routing: $T_STATE (scope: $T_SCOPE, $T_NDOM hosts)"; else ui_err "cannot read the template"; return 1; fi ;;
        *) ui_err "routing: use on | off | status"; return 2 ;;
      esac
      return $? ;;
    scope)
      case ${1:-list} in
        all)  act_run "Scope: all inbounds" foreign_act_scope all ;;
        pick) act_run "Scope" foreign_act_scope ;;
        set)  shift; act_run "Scope" foreign_act_scope "$@" ;;
        list)
          if foreign_facts; then
            ui_say "scope: $T_SCOPE"
            panel_py inbounds "$DB" | awk -F'\x1f' '{printf "  %s  :%s  %s [%s]\n",$1,$2,$3,$4}'
          else ui_err "cannot read the template"; return 1; fi ;;
        *) ui_err "scope: use all | set TAG... | pick | list"; return 2 ;;
      esac
      return $? ;;
    domain | domains)
      case ${1:-list} in
        list)   ACT_QUIET_OK=1 act_run "Domain list" foreign_act_domains_list ;;
        add)    act_run "Add domain" foreign_act_domain_add "${2:-}" ;;
        remove) act_run "Remove domain" foreign_act_domain_remove "${2:-}" ;;
        set)    shift; act_run "Set domain list" foreign_act_domain_set "$@" ;;
        *)      ui_err "domain: use list | add H | remove H | set H..."; return 2 ;;
      esac
      return $? ;;
    sync-iran)    act_run "Sync the Iran relay" foreign_act_sync_iran; return $? ;;
    learn)        act_run "Learn mode" foreign_act_learn; return $? ;;
    learn-restore) act_run "Restore the access log" foreign_act_learn_restore; return $? ;;
    sniffing | audit)
      if [[ $c == audit ]]; then set -- audit "$@"; fi
      case ${1:-audit} in
        audit) act_run "Sniffing audit" foreign_act_sniff_audit ;;
        fix)   act_run "Fix sniffing" foreign_act_sniff_fix "${2:-}" ;;
        *)     ui_err "sniffing: use audit | fix [IDS|all]"; return 2 ;;
      esac
      return $? ;;
    backups)
      case ${1:-list} in
        list)
          while IFS= read -r d; do i=$((i + 1)); printf '  %d) %s  %s\n' "$i" "$(basename "$d")" "$(foreign_bk_summary "$d")"; done < <(bk_dirs)
          if ((i == 0)); then ui_note "(no backups yet)"; fi
          return 0 ;;
        diff)    d=$(foreign_cli_backup_dir "${2:-}") || return $?; ACT_QUIET_OK=1 act_run "Backup diff" foreign_act_backup_diff "$d"; return $? ;;
        restore) d=$(foreign_cli_backup_dir "${2:-}") || return $?; act_run "Restore backup" foreign_act_backup_restore "$d"; return $? ;;
        *)       ui_err "backups: use list | diff N | restore N"; return 2 ;;
      esac ;;
    revert)       act_run "Revert everything" foreign_act_revert; return $? ;;
    rollback)     act_run "Rollback" foreign_act_rollback; return $? ;;
    install-self) act_run "Install this tool" iran_act_install_self; return $? ;;
    help)         foreign_usage; return 0 ;;
    *)            ui_err "unknown foreign command: $c"; foreign_usage >&2; return 2 ;;
  esac
}

# ==== src/entry/gemini-menu.sh ====
# build: app
# gemini-menu - menu and command line for "Gemini via Iran-side Shecan".
#
#   gemini-menu                          interactive menu (the role is remembered)
#   gemini-menu [flags] iran <command>   canonical command line (see: gemini-menu iran help)
#   gemini-menu role [iran|foreign]      show / set the remembered role
#   gemini-menu install-self             install this file as /usr/local/bin/gemini-menu
#
# Both roles live in this engine: IRAN (the relay) and FOREIGN (the 3X-UI panel patcher).

set -uo pipefail
umask 077

ROLE=""
ROLE_FLAG=""
POS=()
ORIG_ARGS=()
FLAG_CMD=""

usage() {
  cat <<EOF
gemini-menu $GM_VERSION - menu and commands for "Gemini via Iran-side Shecan"

  gemini-menu                         interactive menu
  gemini-menu [flags] iran|foreign <command>   run one command (gemini-menu iran help / foreign help)
  gemini-menu role [iran|foreign]     show / set which server this is (remembered in $ROLE_FILE)
  gemini-menu install-self            install this file as $INSTALL_PATH

Global flags: --role iran|foreign  --dry-run  --yes  --no-color  --ascii  --verbose  -h  --version
Iran flags:   --foreign-ip IP  --ss-port N  --key-file F  --shecan-url-file F  --xray-version X.Y.Z
              --xray-bin PATH  --backup-dir D  --rollback
Foreign flags: --iran-ip IP  --key-file F  --ss-port N  --db PATH  --xray-bin PATH  --restart-cmd CMD
              --fix-sniffing  --all-domains  --restore-full-db  --quick  --backup-dir D
Flags may appear before or after the command: 'gemini-menu --yes iran status' = 'gemini-menu iran status --yes'.
EOF
}

# parse_args: flags anywhere, everything else is a positional word. Returns 2 on a usage error.
parse_args() {
  POS=()
  while (($#)); do
    case $1 in
      --role | --foreign-ip | --iran-ip | --ss-port | --key-file | --shecan-url-file | --xray-version | --xray-bin | --backup-dir | --db | --restart-cmd)
        if (($# < 2)); then echo "flag $1 needs a value (see: gemini-menu --help)" >&2; return 2; fi
        case $1 in
          --role)            ROLE_FLAG=$2 ;;
          --foreign-ip)      FOREIGN_IP=$2 ;;
          --iran-ip)         IRAN_IP=$2 ;;
          --db)              DB=$2 ;;
          --restart-cmd)     RESTART_CMD=$2 ;;
          --ss-port)         SS_PORT=$2; SS_PORT_EXPLICIT=1 ;;
          --key-file)        KEY_FILE_ARG=$2 ;;
          --shecan-url-file) SHECAN_URL_FILE_ARG=$2 ;;
          --xray-version)    XRAY_VERSION=$2; XRAY_VERSION_SET=1 ;;
          --xray-bin)        XRAY_BIN_SRC=$2 ;;
          --backup-dir)      BACKUP_DIR_ARG=$2 ;;
          *) ;;
        esac
        shift
        ;;
      --dry-run)  GM_DRY=1 ;;
      --yes | -y) GM_YES=1 ;;
      --no-color) GM_COLOR=0 ;;
      --ascii)    GM_ASCII=1 ;;
      --verbose)  VERBOSE=1 ;;
      --rollback) FLAG_CMD=rollback ;;
      --legacy | --quick) QUICK=1 ;;
      --fix-sniffing)     FIX_SNIFFING=1 ;;
      --all-domains)      ALL_DOMAINS=1 ;;
      --restore-full-db)  RESTORE_FULL_DB=1 ;;
      -h | --help) FLAG_CMD=help ;;
      --version)  FLAG_CMD=version ;;
      --*) echo "unknown flag: $1 (see: gemini-menu --help)" >&2; return 2 ;;
      *) POS+=("$1") ;;
    esac
    shift
  done
}

# Role: --role / $GM_ROLE, else the remembered one, else "the relay is installed here" => iran,
# else ASK ONCE and remember the answer. It is never guessed from other software: an Iran server
# often runs a 3X-UI panel too, and a wrong guess used to be repeated on every start.
resolve_role() {
  local r=${ROLE_FLAG:-${GM_ROLE:-}} pick
  if [[ -z $r ]]; then r=$(role_get); fi
  if [[ -z $r ]] && iran_installed; then r=iran; if ! is_dry; then role_set iran; fi; fi
  if [[ -z $r ]]; then
    if ((!IN_OK)); then
      ui_err "cannot tell which server this is - pass --role iran|foreign (it is remembered after 'setup')"
      return 2
    fi
    ui_blank
    ui_say "First run: which server is this? (asked once, then remembered in $ROLE_FILE)"
    prompt_choice pick "This server is the" "" "Iran server (runs the relay)" "Foreign server (runs the 3X-UI panel)" || return 1
    case $pick in Iran*) r=iran ;; *) r=foreign ;; esac
    if ! is_dry; then role_set "$r"; fi
  fi
  case $r in
    iran | foreign) ROLE=$r ;;
    *) ui_err "role must be iran or foreign (got '$r')"; return 2 ;;
  esac
}

offer_install_self() {
  local sum rc
  if ((!IN_OK)) || is_dry || [[ $EUID -ne 0 || -z $GM_SELF || $GM_SELF == "$INSTALL_PATH" ]]; then return 0; fi
  if [[ -x $INSTALL_PATH ]] && cmp -s "$GM_SELF" "$INSTALL_PATH"; then return 0; fi
  sum=$(md5sum "$GM_SELF" | cut -d' ' -f1)
  if [[ $(state_get install_declined) == "$sum" ]]; then return 0; fi
  ui_blank
  if [[ -x $INSTALL_PATH ]]; then ui_info "A different version of this tool is installed as $INSTALL_PATH."
  else ui_info "First run. This tool can install itself so you only type: gemini-menu (the health timer runs that copy)."; fi
  confirm "Install / update $INSTALL_PATH now?" y
  rc=$?
  if ((rc == 0)); then
    act_run "Install $INSTALL_PATH" iran_act_install_self
  else
    state_set install_declined "$sum"
  fi
}

main() {
  local cmd="" rc=0
  ORIG_ARGS=("$@")
  parse_args "$@" || return $?
  gm_tmp_init
  gm_install_traps
  ui_detect
  in_init
  if [[ -n ${BASH_SOURCE[0]:-} && -r ${BASH_SOURCE[0]} ]]; then GM_SELF=$(readlink -f "${BASH_SOURCE[0]}"); fi

  if [[ $FLAG_CMD == version ]]; then echo "gemini-menu $GM_VERSION (${GM_BUILD:-dev})"; return 0; fi
  if [[ $FLAG_CMD == help || ${POS[0]:-} == help ]]; then usage; return 0; fi

  # `iran` / `foreign` first word selects the role for this one command
  if [[ ${POS[0]:-} == iran || ${POS[0]:-} == foreign ]]; then ROLE_FLAG=${POS[0]}; POS=("${POS[@]:1}"); fi
  cmd=${POS[0]:-}
  if ((${#POS[@]} > 0)); then POS=("${POS[@]:1}"); fi
  if [[ $FLAG_CMD == rollback ]]; then cmd=rollback; fi

  case $cmd in
    role)
      case ${POS[0]:-show} in
        show) echo "role: $(role_get || true)${ROLE_FLAG:+ (this run: $ROLE_FLAG)}"; return 0 ;;
        iran | foreign) if is_dry; then echo "dry-run: would remember role ${POS[0]}"; else role_set "${POS[0]}"; echo "role remembered: ${POS[0]}"; fi; return 0 ;;
        *) ui_err "role: use iran | foreign | show"; return 2 ;;
      esac ;;
    install-self) ROLE=iran; act_run "Install this tool" iran_act_install_self; return $? ;;
  esac

  resolve_role || return $?
  if [[ $ROLE == foreign ]]; then
    MANIFEST=foreign.manifest
    locate_db || true                  # quiet; the dashboard says so when it stays empty
    locate_xray || true
    foreign_register_probes
    foreign_screens
  else
    iran_register_probes
    iran_screens
  fi
  if [[ -n $cmd ]]; then
    if [[ $ROLE == foreign ]]; then foreign_cli "$cmd" "${POS[@]}"; else iran_cli "$cmd" "${POS[@]}"; fi
    return $?
  fi
  if ((!IN_OK)); then
    ui_err "the menu needs a terminal - run a command instead (gemini-menu $ROLE help)"
    return 1
  fi
  offer_install_self
  gm_audit "menu opened"
  ui_banner "GEMINI $G_DOT SHECAN" "$([[ $ROLE == foreign ]] && echo 'Foreign server manager' || echo 'Iran relay manager') $G_DOT v$GM_VERSION"
  menu_run main        # its own statement (never after || / if): see src/lib/40-action.sh
  rc=$?
  ui_blank
  ui_note "bye"
  return "$rc"
}

# Runs when executed or piped into bash (curl ... | bash); stays quiet when sourced by tests.
if [[ -z ${BASH_SOURCE[0]:-} || ${BASH_SOURCE[0]} == "$0" ]]; then
  main "$@"
  exit $?
fi
